begin;
-- Seed the six newly authored Grade 10 introductory courses. Content is partial, not a full-year claim.
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'placement', 0, 'PLACEMENT', 'Khảo sát đầu vào', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"math-10-sets-q1","prompt":"Kí hiệu nào diễn tả 2 thuộc tập A?","difficulty":"EASY","options":[{"id":"a","text":"2 ∈ A"},{"id":"b","text":"A ∈ 2"},{"id":"c","text":"2 ⊂ A"}],"correctOptionId":"a","explanation":"∈ diễn tả quan hệ giữa một phần tử và một tập hợp."},{"id":"math-10-sets-q2","prompt":"A={1,2,3}, B={2,3,4}. A∩B là gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"{1,4}"},{"id":"b","text":"{1,2,3,4}"},{"id":"c","text":"{2,3}"}],"correctOptionId":"c","explanation":"Giao gồm phần tử có mặt trong cả hai tập."},{"id":"math-10-intervals-q1","prompt":"Đoạn [−1;4] có chứa đầu mút 4 không?","difficulty":"EASY","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ khi 4 âm"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Dấu ngoặc vuông cho biết đầu mút được lấy."},{"id":"math-10-intervals-q2","prompt":"|−7| bằng bao nhiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"0"},{"id":"b","text":"7"},{"id":"c","text":"−7"}],"correctOptionId":"b","explanation":"Giá trị tuyệt đối là khoảng cách nên không âm."},{"id":"math-10-linear-inequalities-q1","prompt":"Khi chia hai vế bất đẳng thức cho số âm, cần làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Đổi dấu cả hai vế thành bằng"},{"id":"b","text":"Đổi chiều dấu"},{"id":"c","text":"Giữ nguyên dấu"}],"correctOptionId":"b","explanation":"Nhân hoặc chia với số âm làm thứ tự trên trục số đảo ngược."},{"id":"math-10-linear-inequalities-q2","prompt":"Nghiệm của 3x+1≥7 là?","difficulty":"MEDIUM","options":[{"id":"a","text":"x≥2"},{"id":"b","text":"x≤2"},{"id":"c","text":"x≥6"}],"correctOptionId":"a","explanation":"Trừ 1 rồi chia 3: 3x≥6."},{"id":"math-10-systems-regions-q1","prompt":"Miền nghiệm của hệ gồm những điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Thỏa đồng thời mọi bất phương trình"},{"id":"b","text":"Chỉ thỏa một bất phương trình bất kỳ"},{"id":"c","text":"Không cần thay tọa độ"}],"correctOptionId":"a","explanation":"Nghiệm hệ phải làm tất cả các điều kiện cùng đúng."},{"id":"math-10-systems-regions-q2","prompt":"Điểm (2,1) có thỏa x≥0, y≥0 không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ thỏa x≥0"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Cả hai tọa độ đều không âm."},{"id":"math-10-quadratic-function-q1","prompt":"Đồ thị hàm số bậc hai là hình nào?","difficulty":"EASY","options":[{"id":"a","text":"Đường tròn"},{"id":"b","text":"Đường thẳng luôn luôn"},{"id":"c","text":"Parabol"}],"correctOptionId":"c","explanation":"Biểu thức bậc hai theo x tạo nên đồ thị parabol."},{"id":"math-10-quadratic-function-q2","prompt":"y=−x²+3 mở về phía nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không có đồ thị"},{"id":"b","text":"Mở xuống"},{"id":"c","text":"Mở lên"}],"correctOptionId":"b","explanation":"Hệ số a âm nên hai nhánh hướng xuống."}]'::jsonb, '[]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-sets', 1, 'LESSON', 'Tập hợp và cách biểu diễn', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Tập hợp gom các đối tượng xác định rõ. Kí hiệu x ∈ A nghĩa là x thuộc A; A ⊂ B nghĩa là mọi phần tử của A đều thuộc B."]'::jsonb, '["A={1,2,3}, B={2,3,4} thì A∩B={2,3} và A∪B={1,2,3,4}."]'::jsonb, '[{"id":"math-10-sets-q1","prompt":"Kí hiệu nào diễn tả 2 thuộc tập A?","difficulty":"EASY","options":[{"id":"a","text":"2 ∈ A"},{"id":"b","text":"A ∈ 2"},{"id":"c","text":"2 ⊂ A"}],"correctOptionId":"a","explanation":"∈ diễn tả quan hệ giữa một phần tử và một tập hợp."},{"id":"math-10-sets-q2","prompt":"A={1,2,3}, B={2,3,4}. A∩B là gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"{1,4}"},{"id":"b","text":"{1,2,3,4}"},{"id":"c","text":"{2,3}"}],"correctOptionId":"c","explanation":"Giao gồm phần tử có mặt trong cả hai tập."},{"id":"math-10-sets-q3","prompt":"Lớp 10A có 18 bạn thích Toán, 12 bạn thích Anh, 5 bạn thích cả hai. Có bao nhiêu bạn thích ít nhất một môn?","difficulty":"APPLIED","options":[{"id":"a","text":"35"},{"id":"b","text":"25"},{"id":"c","text":"30"}],"correctOptionId":"b","explanation":"Dùng |A∪B|=|A|+|B|−|A∩B|=18+12−5."}]'::jsonb, '["math-10-sets"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-intervals', 2, 'LESSON', 'Khoảng, đoạn và giá trị tuyệt đối', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Khoảng (a;b) không lấy hai đầu mút; đoạn [a;b] có lấy hai đầu mút. |x| là khoảng cách từ x đến 0 trên trục số."]'::jsonb, '["|x−3|≤2 tương đương 1≤x≤5, tức x∈[1;5]."]'::jsonb, '[{"id":"math-10-intervals-q1","prompt":"Đoạn [−1;4] có chứa đầu mút 4 không?","difficulty":"EASY","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ khi 4 âm"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Dấu ngoặc vuông cho biết đầu mút được lấy."},{"id":"math-10-intervals-q2","prompt":"|−7| bằng bao nhiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"0"},{"id":"b","text":"7"},{"id":"c","text":"−7"}],"correctOptionId":"b","explanation":"Giá trị tuyệt đối là khoảng cách nên không âm."},{"id":"math-10-intervals-q3","prompt":"Điều kiện |x−2|<3 tương đương khoảng nào?","difficulty":"APPLIED","options":[{"id":"a","text":"(−1;5)"},{"id":"b","text":"[−1;5]"},{"id":"c","text":"(2;5)"}],"correctOptionId":"a","explanation":"Bất đẳng thức tương đương −3<x−2<3; cộng 2 vào ba vế."}]'::jsonb, '["math-10-intervals"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-linear-inequalities', 3, 'LESSON', 'Bất phương trình bậc nhất một ẩn', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Giải bất phương trình là tìm mọi giá trị của ẩn làm mệnh đề đúng. Khi nhân hoặc chia hai vế cho số âm, phải đổi chiều bất đẳng thức."]'::jsonb, '["−2x<6 suy ra x>−3 vì chia cả hai vế cho −2."]'::jsonb, '[{"id":"math-10-linear-inequalities-q1","prompt":"Khi chia hai vế bất đẳng thức cho số âm, cần làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Đổi dấu cả hai vế thành bằng"},{"id":"b","text":"Đổi chiều dấu"},{"id":"c","text":"Giữ nguyên dấu"}],"correctOptionId":"b","explanation":"Nhân hoặc chia với số âm làm thứ tự trên trục số đảo ngược."},{"id":"math-10-linear-inequalities-q2","prompt":"Nghiệm của 3x+1≥7 là?","difficulty":"MEDIUM","options":[{"id":"a","text":"x≥2"},{"id":"b","text":"x≤2"},{"id":"c","text":"x≥6"}],"correctOptionId":"a","explanation":"Trừ 1 rồi chia 3: 3x≥6."},{"id":"math-10-linear-inequalities-q3","prompt":"Một chuyến xe có phí 20 nghìn và mỗi km 8 nghìn. Ngân sách tối đa 100 nghìn. Số km d thỏa điều kiện nào?","difficulty":"APPLIED","options":[{"id":"a","text":"20d+8≤100"},{"id":"b","text":"8(d+20)=100"},{"id":"c","text":"20+8d≤100"}],"correctOptionId":"c","explanation":"Tổng tiền gồm phí cố định và tiền theo quãng đường, không vượt ngân sách."}]'::jsonb, '["math-10-linear-inequalities"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-systems-regions', 4, 'LESSON', 'Hệ bất phương trình và miền nghiệm', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Mỗi bất phương trình hai ẩn xác định một nửa mặt phẳng. Miền nghiệm của hệ là phần giao các miền tương ứng."]'::jsonb, '["x≥0 và y≥0 chọn góc phần tư thứ nhất kể cả hai trục."]'::jsonb, '[{"id":"math-10-systems-regions-q1","prompt":"Miền nghiệm của hệ gồm những điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Thỏa đồng thời mọi bất phương trình"},{"id":"b","text":"Chỉ thỏa một bất phương trình bất kỳ"},{"id":"c","text":"Không cần thay tọa độ"}],"correctOptionId":"a","explanation":"Nghiệm hệ phải làm tất cả các điều kiện cùng đúng."},{"id":"math-10-systems-regions-q2","prompt":"Điểm (2,1) có thỏa x≥0, y≥0 không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ thỏa x≥0"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Cả hai tọa độ đều không âm."},{"id":"math-10-systems-regions-q3","prompt":"Một cửa hàng cần x hộp loại A, y hộp loại B; tổng không quá 10 hộp và mỗi loại ít nhất 2. Hệ điều kiện là?","difficulty":"APPLIED","options":[{"id":"a","text":"xy≤10"},{"id":"b","text":"x+y≤10, x≥2, y≥2"},{"id":"c","text":"x+y≥10, x≤2, y≤2"}],"correctOptionId":"b","explanation":"Tổng số hộp bị chặn trên; mỗi số lượng có chặn dưới."}]'::jsonb, '["math-10-systems-regions"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-quadratic-function', 5, 'LESSON', 'Hàm số bậc hai và đồ thị', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Hàm số bậc hai có dạng y=ax²+bx+c, a≠0. Đồ thị là parabol; dấu của a quyết định parabol mở lên hay mở xuống."]'::jsonb, '["y=2x² mở lên vì a=2>0."]'::jsonb, '[{"id":"math-10-quadratic-function-q1","prompt":"Đồ thị hàm số bậc hai là hình nào?","difficulty":"EASY","options":[{"id":"a","text":"Đường tròn"},{"id":"b","text":"Đường thẳng luôn luôn"},{"id":"c","text":"Parabol"}],"correctOptionId":"c","explanation":"Biểu thức bậc hai theo x tạo nên đồ thị parabol."},{"id":"math-10-quadratic-function-q2","prompt":"y=−x²+3 mở về phía nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không có đồ thị"},{"id":"b","text":"Mở xuống"},{"id":"c","text":"Mở lên"}],"correctOptionId":"b","explanation":"Hệ số a âm nên hai nhánh hướng xuống."},{"id":"math-10-quadratic-function-q3","prompt":"Một vật được phóng lên có độ cao h(t)=−5t²+20t. Đồ thị giúp tìm thời điểm đạt độ cao cực đại bằng cách nào?","difficulty":"APPLIED","options":[{"id":"a","text":"Tìm hoành độ đỉnh parabol"},{"id":"b","text":"Tìm giao điểm với trục Oy"},{"id":"c","text":"Lấy hệ số tự do"}],"correctOptionId":"a","explanation":"Parabol mở xuống nên đỉnh biểu diễn giá trị lớn nhất."}]'::jsonb, '["math-10-quadratic-function"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-review-1', 6, 'FIVE_LESSON_REVIEW', 'Ôn tập 1', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"math-10-sets-q1","prompt":"Kí hiệu nào diễn tả 2 thuộc tập A?","difficulty":"EASY","options":[{"id":"a","text":"2 ∈ A"},{"id":"b","text":"A ∈ 2"},{"id":"c","text":"2 ⊂ A"}],"correctOptionId":"a","explanation":"∈ diễn tả quan hệ giữa một phần tử và một tập hợp."},{"id":"math-10-sets-q2","prompt":"A={1,2,3}, B={2,3,4}. A∩B là gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"{1,4}"},{"id":"b","text":"{1,2,3,4}"},{"id":"c","text":"{2,3}"}],"correctOptionId":"c","explanation":"Giao gồm phần tử có mặt trong cả hai tập."},{"id":"math-10-intervals-q1","prompt":"Đoạn [−1;4] có chứa đầu mút 4 không?","difficulty":"EASY","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ khi 4 âm"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Dấu ngoặc vuông cho biết đầu mút được lấy."},{"id":"math-10-intervals-q2","prompt":"|−7| bằng bao nhiêu?","difficulty":"MEDIUM","options":[{"id":"a","text":"0"},{"id":"b","text":"7"},{"id":"c","text":"−7"}],"correctOptionId":"b","explanation":"Giá trị tuyệt đối là khoảng cách nên không âm."},{"id":"math-10-linear-inequalities-q1","prompt":"Khi chia hai vế bất đẳng thức cho số âm, cần làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Đổi dấu cả hai vế thành bằng"},{"id":"b","text":"Đổi chiều dấu"},{"id":"c","text":"Giữ nguyên dấu"}],"correctOptionId":"b","explanation":"Nhân hoặc chia với số âm làm thứ tự trên trục số đảo ngược."},{"id":"math-10-linear-inequalities-q2","prompt":"Nghiệm của 3x+1≥7 là?","difficulty":"MEDIUM","options":[{"id":"a","text":"x≥2"},{"id":"b","text":"x≤2"},{"id":"c","text":"x≥6"}],"correctOptionId":"a","explanation":"Trừ 1 rồi chia 3: 3x≥6."},{"id":"math-10-systems-regions-q1","prompt":"Miền nghiệm của hệ gồm những điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Thỏa đồng thời mọi bất phương trình"},{"id":"b","text":"Chỉ thỏa một bất phương trình bất kỳ"},{"id":"c","text":"Không cần thay tọa độ"}],"correctOptionId":"a","explanation":"Nghiệm hệ phải làm tất cả các điều kiện cùng đúng."},{"id":"math-10-systems-regions-q2","prompt":"Điểm (2,1) có thỏa x≥0, y≥0 không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không"},{"id":"b","text":"Chỉ thỏa x≥0"},{"id":"c","text":"Có"}],"correctOptionId":"c","explanation":"Cả hai tọa độ đều không âm."},{"id":"math-10-quadratic-function-q1","prompt":"Đồ thị hàm số bậc hai là hình nào?","difficulty":"EASY","options":[{"id":"a","text":"Đường tròn"},{"id":"b","text":"Đường thẳng luôn luôn"},{"id":"c","text":"Parabol"}],"correctOptionId":"c","explanation":"Biểu thức bậc hai theo x tạo nên đồ thị parabol."},{"id":"math-10-quadratic-function-q2","prompt":"y=−x²+3 mở về phía nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không có đồ thị"},{"id":"b","text":"Mở xuống"},{"id":"c","text":"Mở lên"}],"correctOptionId":"b","explanation":"Hệ số a âm nên hai nhánh hướng xuống."}]'::jsonb, '["math-10-sets","math-10-intervals","math-10-linear-inequalities","math-10-systems-regions","math-10-quadratic-function"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-quadratic-sign', 7, 'LESSON', 'Dấu tam thức bậc hai', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Nghiệm của ax²+bx+c=0 chia trục số thành các khoảng. Với hai nghiệm phân biệt, tam thức cùng dấu với a ở ngoài hai nghiệm và trái dấu với a ở giữa."]'::jsonb, '["x²−5x+6=(x−2)(x−3) âm khi 2<x<3."]'::jsonb, '[{"id":"math-10-quadratic-sign-q1","prompt":"Khi tam thức có hai nghiệm phân biệt, dấu ở ngoài hai nghiệm cùng hay trái dấu với a?","difficulty":"EASY","options":[{"id":"a","text":"Luôn bằng 0"},{"id":"b","text":"Cùng dấu"},{"id":"c","text":"Trái dấu"}],"correctOptionId":"b","explanation":"Quy tắc dấu cho tam thức bậc hai cho dấu cùng a ở hai miền ngoài."},{"id":"math-10-quadratic-sign-q2","prompt":"x²−4 âm trên khoảng nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"(−2;2)"},{"id":"b","text":"(−∞;−2)∪(2;+∞)"},{"id":"c","text":"Chỉ tại x=2"}],"correctOptionId":"a","explanation":"x²−4=(x−2)(x+2), tam thức âm giữa hai nghiệm."},{"id":"math-10-quadratic-sign-q3","prompt":"Để x²−2x−3≤0, chọn tập nghiệm nào?","difficulty":"APPLIED","options":[{"id":"a","text":"(−∞;−1]∪[3;+∞)"},{"id":"b","text":"(−1;3)"},{"id":"c","text":"[−1;3]"}],"correctOptionId":"c","explanation":"Tam thức có nghiệm −1 và 3, hệ số đầu dương; lấy phần giữa, kể cả hai nghiệm."}]'::jsonb, '["math-10-quadratic-sign"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-quadratic-equations', 8, 'LESSON', 'Phương trình bậc hai', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Với ax²+bx+c=0, biệt thức Δ=b²−4ac cho biết số nghiệm thực: Δ>0 có hai nghiệm, Δ=0 có nghiệm kép, Δ<0 không có nghiệm thực."]'::jsonb, '["x²−5x+6=0 có Δ=1 và nghiệm 2, 3."]'::jsonb, '[{"id":"math-10-quadratic-equations-q1","prompt":"Nếu Δ<0 thì phương trình bậc hai có bao nhiêu nghiệm thực?","difficulty":"EASY","options":[{"id":"a","text":"Không có nghiệm thực"},{"id":"b","text":"Hai nghiệm thực phân biệt"},{"id":"c","text":"Một nghiệm kép"}],"correctOptionId":"a","explanation":"Biệt thức âm loại trừ giao điểm thực với trục hoành."},{"id":"math-10-quadratic-equations-q2","prompt":"Phương trình x²−5x+6=0 có nghiệm nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"−2 và −3"},{"id":"b","text":"1 và 6"},{"id":"c","text":"2 và 3"}],"correctOptionId":"c","explanation":"Phân tích thành (x−2)(x−3)=0."},{"id":"math-10-quadratic-equations-q3","prompt":"Diện tích hình chữ nhật 24 m², chiều dài hơn chiều rộng 2 m. Nếu rộng x, phương trình phù hợp là?","difficulty":"APPLIED","options":[{"id":"a","text":"x²−2=24"},{"id":"b","text":"x(x+2)=24"},{"id":"c","text":"2x+24=0"}],"correctOptionId":"b","explanation":"Diện tích bằng rộng nhân dài; chiều dài là x+2."}]'::jsonb, '["math-10-quadratic-equations"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-trigonometry', 9, 'LESSON', 'Tỉ số lượng giác trong tam giác vuông', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Trong tam giác vuông, sin góc nhọn bằng cạnh đối/huyền, cos bằng cạnh kề/huyền, tan bằng cạnh đối/kề."]'::jsonb, '["Tam giác có cạnh đối 3, kề 4, huyền 5 thì sin α=3/5, cos α=4/5."]'::jsonb, '[{"id":"math-10-trigonometry-q1","prompt":"sin α trong tam giác vuông bằng tỉ số nào?","difficulty":"EASY","options":[{"id":"a","text":"Cạnh kề / cạnh huyền"},{"id":"b","text":"Cạnh đối / cạnh kề"},{"id":"c","text":"Cạnh đối / cạnh huyền"}],"correctOptionId":"c","explanation":"Định nghĩa sin dùng cạnh đối chia cạnh huyền."},{"id":"math-10-trigonometry-q2","prompt":"Cạnh đối 6, cạnh kề 8. tan α bằng?","difficulty":"MEDIUM","options":[{"id":"a","text":"6/8²"},{"id":"b","text":"3/4"},{"id":"c","text":"4/3"}],"correctOptionId":"b","explanation":"tan α=6/8=3/4."},{"id":"math-10-trigonometry-q3","prompt":"Một dốc cao 1 m, chiều ngang 5 m. Góc nghiêng α với mặt đất có tan α bằng?","difficulty":"APPLIED","options":[{"id":"a","text":"1/5"},{"id":"b","text":"5"},{"id":"c","text":"1/25"}],"correctOptionId":"a","explanation":"Tang bằng độ cao chia chiều ngang trong tam giác vuông."}]'::jsonb, '["math-10-trigonometry"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-vectors', 10, 'LESSON', 'Vectơ và phép cộng', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Vectơ có hướng và độ dài. Hai vectơ bằng nhau khi cùng hướng và cùng độ dài; quy tắc hình bình hành hoặc quy tắc nối đuôi dùng để cộng vectơ."]'::jsonb, '["Đi 3 km về đông rồi 4 km về bắc, vectơ tổng là đường chéo hướng đông-bắc."]'::jsonb, '[{"id":"math-10-vectors-q1","prompt":"Hai vectơ bằng nhau cần có điều kiện nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ cùng độ dài"},{"id":"b","text":"Cùng hướng và cùng độ dài"},{"id":"c","text":"Cùng điểm đầu"}],"correctOptionId":"b","explanation":"Điểm đặt không quyết định vectơ tự do; hướng và độ dài mới quyết định."},{"id":"math-10-vectors-q2","prompt":"Nếu AB⃗ và BC⃗ nối tiếp, tổng bằng vectơ nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"AC⃗"},{"id":"b","text":"CA⃗"},{"id":"c","text":"AB⃗−BC⃗"}],"correctOptionId":"a","explanation":"Quy tắc ba điểm cho AB⃗+BC⃗=AC⃗."},{"id":"math-10-vectors-q3","prompt":"Bạn đi 3 km đông rồi 4 km bắc. Độ lớn độ dời là?","difficulty":"APPLIED","options":[{"id":"a","text":"7 km"},{"id":"b","text":"1 km"},{"id":"c","text":"5 km"}],"correctOptionId":"c","explanation":"Hai hướng vuông góc nên dùng định lý Pythagore: √(3²+4²)=5."}]'::jsonb, '["math-10-vectors"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-dot-product', 11, 'LESSON', 'Tích vô hướng và góc', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Tích vô hướng a⃗·b⃗=|a⃗||b⃗|cosθ. Nếu hai vectơ vuông góc thì tích vô hướng bằng 0."]'::jsonb, '["Hai vectơ đơn vị tạo góc 60° có tích vô hướng bằng cos60°=1/2."]'::jsonb, '[{"id":"math-10-dot-product-q1","prompt":"Hai vectơ vuông góc có tích vô hướng bằng bao nhiêu?","difficulty":"EASY","options":[{"id":"a","text":"0"},{"id":"b","text":"1"},{"id":"c","text":"Tích độ dài"}],"correctOptionId":"a","explanation":"cos90°=0 nên tích vô hướng bằng 0."},{"id":"math-10-dot-product-q2","prompt":"Hai vectơ đơn vị tạo góc 60°. Tích vô hướng là?","difficulty":"MEDIUM","options":[{"id":"a","text":"√3/2"},{"id":"b","text":"−1/2"},{"id":"c","text":"1/2"}],"correctOptionId":"c","explanation":"Tích bằng 1·1·cos60°=1/2."},{"id":"math-10-dot-product-q3","prompt":"Hai lực vuông góc có hợp lực độ lớn 3 N và 4 N. Công thức kiểm tra độ lớn hợp lực là?","difficulty":"APPLIED","options":[{"id":"a","text":"3×4"},{"id":"b","text":"√(3²+4²)"},{"id":"c","text":"3+4 luôn luôn"}],"correctOptionId":"b","explanation":"Hai vectơ vuông góc tạo tam giác vuông khi cộng."}]'::jsonb, '["math-10-dot-product"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-review-2', 12, 'FIVE_LESSON_REVIEW', 'Ôn tập 2', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"math-10-quadratic-sign-q1","prompt":"Khi tam thức có hai nghiệm phân biệt, dấu ở ngoài hai nghiệm cùng hay trái dấu với a?","difficulty":"EASY","options":[{"id":"a","text":"Luôn bằng 0"},{"id":"b","text":"Cùng dấu"},{"id":"c","text":"Trái dấu"}],"correctOptionId":"b","explanation":"Quy tắc dấu cho tam thức bậc hai cho dấu cùng a ở hai miền ngoài."},{"id":"math-10-quadratic-sign-q2","prompt":"x²−4 âm trên khoảng nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"(−2;2)"},{"id":"b","text":"(−∞;−2)∪(2;+∞)"},{"id":"c","text":"Chỉ tại x=2"}],"correctOptionId":"a","explanation":"x²−4=(x−2)(x+2), tam thức âm giữa hai nghiệm."},{"id":"math-10-quadratic-equations-q1","prompt":"Nếu Δ<0 thì phương trình bậc hai có bao nhiêu nghiệm thực?","difficulty":"EASY","options":[{"id":"a","text":"Không có nghiệm thực"},{"id":"b","text":"Hai nghiệm thực phân biệt"},{"id":"c","text":"Một nghiệm kép"}],"correctOptionId":"a","explanation":"Biệt thức âm loại trừ giao điểm thực với trục hoành."},{"id":"math-10-quadratic-equations-q2","prompt":"Phương trình x²−5x+6=0 có nghiệm nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"−2 và −3"},{"id":"b","text":"1 và 6"},{"id":"c","text":"2 và 3"}],"correctOptionId":"c","explanation":"Phân tích thành (x−2)(x−3)=0."},{"id":"math-10-trigonometry-q1","prompt":"sin α trong tam giác vuông bằng tỉ số nào?","difficulty":"EASY","options":[{"id":"a","text":"Cạnh kề / cạnh huyền"},{"id":"b","text":"Cạnh đối / cạnh kề"},{"id":"c","text":"Cạnh đối / cạnh huyền"}],"correctOptionId":"c","explanation":"Định nghĩa sin dùng cạnh đối chia cạnh huyền."},{"id":"math-10-trigonometry-q2","prompt":"Cạnh đối 6, cạnh kề 8. tan α bằng?","difficulty":"MEDIUM","options":[{"id":"a","text":"6/8²"},{"id":"b","text":"3/4"},{"id":"c","text":"4/3"}],"correctOptionId":"b","explanation":"tan α=6/8=3/4."},{"id":"math-10-vectors-q1","prompt":"Hai vectơ bằng nhau cần có điều kiện nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ cùng độ dài"},{"id":"b","text":"Cùng hướng và cùng độ dài"},{"id":"c","text":"Cùng điểm đầu"}],"correctOptionId":"b","explanation":"Điểm đặt không quyết định vectơ tự do; hướng và độ dài mới quyết định."},{"id":"math-10-vectors-q2","prompt":"Nếu AB⃗ và BC⃗ nối tiếp, tổng bằng vectơ nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"AC⃗"},{"id":"b","text":"CA⃗"},{"id":"c","text":"AB⃗−BC⃗"}],"correctOptionId":"a","explanation":"Quy tắc ba điểm cho AB⃗+BC⃗=AC⃗."},{"id":"math-10-dot-product-q1","prompt":"Hai vectơ vuông góc có tích vô hướng bằng bao nhiêu?","difficulty":"EASY","options":[{"id":"a","text":"0"},{"id":"b","text":"1"},{"id":"c","text":"Tích độ dài"}],"correctOptionId":"a","explanation":"cos90°=0 nên tích vô hướng bằng 0."},{"id":"math-10-dot-product-q2","prompt":"Hai vectơ đơn vị tạo góc 60°. Tích vô hướng là?","difficulty":"MEDIUM","options":[{"id":"a","text":"√3/2"},{"id":"b","text":"−1/2"},{"id":"c","text":"1/2"}],"correctOptionId":"c","explanation":"Tích bằng 1·1·cos60°=1/2."}]'::jsonb, '["math-10-quadratic-sign","math-10-quadratic-equations","math-10-trigonometry","math-10-vectors","math-10-dot-product"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-coordinates-vectors', 13, 'LESSON', 'Tọa độ vectơ trong mặt phẳng', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Với A(x₁;y₁), B(x₂;y₂), vectơ AB⃗=(x₂−x₁;y₂−y₁). Độ dài vectơ (u;v) là √(u²+v²)."]'::jsonb, '["A(1;2), B(4;6) thì AB⃗=(3;4), độ dài bằng 5."]'::jsonb, '[{"id":"math-10-coordinates-vectors-q1","prompt":"Tọa độ AB⃗ được tính theo thứ tự nào?","difficulty":"EASY","options":[{"id":"a","text":"A trừ B"},{"id":"b","text":"Cộng hai điểm"},{"id":"c","text":"B trừ A"}],"correctOptionId":"c","explanation":"Vectơ đi từ A đến B nên lấy tọa độ cuối trừ đầu."},{"id":"math-10-coordinates-vectors-q2","prompt":"A(−1;2), B(2;6). AB⃗ là?","difficulty":"MEDIUM","options":[{"id":"a","text":"(1;8)"},{"id":"b","text":"(3;4)"},{"id":"c","text":"(−3;−4)"}],"correctOptionId":"b","explanation":"(2−(−1);6−2)=(3;4)."},{"id":"math-10-coordinates-vectors-q3","prompt":"Vectơ dịch chuyển (5;12) có độ dài bao nhiêu đơn vị?","difficulty":"APPLIED","options":[{"id":"a","text":"13"},{"id":"b","text":"17"},{"id":"c","text":"7"}],"correctOptionId":"a","explanation":"Độ dài bằng √(25+144)=13."}]'::jsonb, '["math-10-coordinates-vectors"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-coordinate-line', 14, 'LESSON', 'Phương trình đường thẳng', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Dạng ax+by+c=0 mô tả đường thẳng khi a và b không đồng thời bằng 0. Vectơ pháp tuyến (a;b) vuông góc với đường thẳng."]'::jsonb, '["2x−y+1=0 có vectơ pháp tuyến (2;−1)."]'::jsonb, '[{"id":"math-10-coordinate-line-q1","prompt":"Trong ax+by+c=0, một vectơ pháp tuyến là?","difficulty":"EASY","options":[{"id":"a","text":"(c;0)"},{"id":"b","text":"(a;b)"},{"id":"c","text":"(−b;a) luôn là pháp tuyến"}],"correctOptionId":"b","explanation":"Các hệ số của x,y tạo vectơ vuông góc với đường thẳng."},{"id":"math-10-coordinate-line-q2","prompt":"Điểm (1;1) có thuộc đường thẳng x+y−2=0 không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Có"},{"id":"b","text":"Không"},{"id":"c","text":"Chỉ khi x=0"}],"correctOptionId":"a","explanation":"Thay vào: 1+1−2=0."},{"id":"math-10-coordinate-line-q3","prompt":"Đường thẳng qua (0;2) và song song trục Ox có phương trình?","difficulty":"APPLIED","options":[{"id":"a","text":"x=2"},{"id":"b","text":"x+y=2"},{"id":"c","text":"y=2"}],"correctOptionId":"c","explanation":"Đường ngang giữ tung độ không đổi."}]'::jsonb, '["math-10-coordinate-line"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-counting', 15, 'LESSON', 'Quy tắc cộng và quy tắc nhân', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Quy tắc cộng dùng cho các lựa chọn loại trừ nhau; quy tắc nhân dùng cho các bước lựa chọn nối tiếp."]'::jsonb, '["Chọn 1 áo trong 3 và 1 quần trong 2 có 3×2=6 bộ."]'::jsonb, '[{"id":"math-10-counting-q1","prompt":"Chọn áo rồi chọn quần là các bước nối tiếp, thường dùng quy tắc nào?","difficulty":"EASY","options":[{"id":"a","text":"Quy tắc nhân"},{"id":"b","text":"Quy tắc cộng"},{"id":"c","text":"Quy tắc trừ"}],"correctOptionId":"a","explanation":"Mỗi kết quả gồm một lựa chọn ở mỗi bước nên nhân số cách."},{"id":"math-10-counting-q2","prompt":"Có 4 món tráng miệng hoặc 3 loại nước, chọn đúng một món. Có bao nhiêu cách?","difficulty":"MEDIUM","options":[{"id":"a","text":"12"},{"id":"b","text":"1"},{"id":"c","text":"7"}],"correctOptionId":"c","explanation":"Hai nhóm lựa chọn loại trừ nhau nên cộng 4+3."},{"id":"math-10-counting-q3","prompt":"Mật khẩu gồm 2 chữ số, mỗi vị trí chọn từ 0–9 và được lặp. Có bao nhiêu mật khẩu?","difficulty":"APPLIED","options":[{"id":"a","text":"90"},{"id":"b","text":"100"},{"id":"c","text":"20"}],"correctOptionId":"b","explanation":"Mỗi vị trí có 10 lựa chọn độc lập: 10×10."}]'::jsonb, '["math-10-counting"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-combinations', 16, 'LESSON', 'Hoán vị và tổ hợp', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Hoán vị xét thứ tự sắp xếp tất cả phần tử; tổ hợp chọn một nhóm mà không xét thứ tự. C_n^k=n!/(k!(n−k)!)."]'::jsonb, '["Chọn 2 bạn từ 5 bạn có C(5,2)=10 nhóm."]'::jsonb, '[{"id":"math-10-combinations-q1","prompt":"Chọn một ban gồm 3 bạn từ 8 bạn, không phân chức vụ, dùng dạng nào?","difficulty":"EASY","options":[{"id":"a","text":"Hoán vị"},{"id":"b","text":"Chỉnh hợp có lặp"},{"id":"c","text":"Tổ hợp"}],"correctOptionId":"c","explanation":"Không phân chức vụ nên thứ tự chọn không tạo nhóm mới."},{"id":"math-10-combinations-q2","prompt":"C(5,2) bằng?","difficulty":"MEDIUM","options":[{"id":"a","text":"5"},{"id":"b","text":"10"},{"id":"c","text":"20"}],"correctOptionId":"b","explanation":"5·4/(2·1)=10."},{"id":"math-10-combinations-q3","prompt":"Xếp 4 quyển sách khác nhau thành một hàng có bao nhiêu cách?","difficulty":"APPLIED","options":[{"id":"a","text":"24"},{"id":"b","text":"16"},{"id":"c","text":"4"}],"correctOptionId":"a","explanation":"Có 4!=24 hoán vị vì vị trí mỗi quyển khác nhau."}]'::jsonb, '["math-10-combinations"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-statistics', 17, 'LESSON', 'Mô tả và đọc dữ liệu', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Số trung bình mô tả tâm dữ liệu; trung vị chia dãy đã sắp xếp thành hai nửa; khoảng biến thiên bằng giá trị lớn nhất trừ nhỏ nhất."]'::jsonb, '["Dữ liệu 2,3,3,8 có trung vị (3+3)/2=3 và khoảng biến thiên 6."]'::jsonb, '[{"id":"math-10-statistics-q1","prompt":"Khoảng biến thiên bằng gì?","difficulty":"EASY","options":[{"id":"a","text":"Giá trị ở giữa"},{"id":"b","text":"Giá trị lớn nhất trừ nhỏ nhất"},{"id":"c","text":"Tổng chia số phần tử"}],"correctOptionId":"b","explanation":"Khoảng biến thiên đo độ rộng từ đầu nhỏ đến đầu lớn."},{"id":"math-10-statistics-q2","prompt":"Trung vị của 1,4,7 là?","difficulty":"MEDIUM","options":[{"id":"a","text":"4"},{"id":"b","text":"1"},{"id":"c","text":"7"}],"correctOptionId":"a","explanation":"Dãy đã sắp xếp có phần tử chính giữa là 4."},{"id":"math-10-statistics-q3","prompt":"Hai nhóm có cùng trung bình nhưng một nhóm phân tán rộng hơn. Chỉ số nào gợi ý khác biệt này?","difficulty":"APPLIED","options":[{"id":"a","text":"Số phần tử luôn luôn"},{"id":"b","text":"Trung bình"},{"id":"c","text":"Khoảng biến thiên hoặc độ lệch chuẩn"}],"correctOptionId":"c","explanation":"Chỉ số phân tán bổ sung thông tin mà trung bình không cho biết."}]'::jsonb, '["math-10-statistics"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('math', 10, 'intro-2026.1', 'math-10-review-3', 18, 'FIVE_LESSON_REVIEW', 'Ôn tập 3', 'Toán: nền tảng đại số, hình học và dữ liệu', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"math-10-coordinates-vectors-q1","prompt":"Tọa độ AB⃗ được tính theo thứ tự nào?","difficulty":"EASY","options":[{"id":"a","text":"A trừ B"},{"id":"b","text":"Cộng hai điểm"},{"id":"c","text":"B trừ A"}],"correctOptionId":"c","explanation":"Vectơ đi từ A đến B nên lấy tọa độ cuối trừ đầu."},{"id":"math-10-coordinates-vectors-q2","prompt":"A(−1;2), B(2;6). AB⃗ là?","difficulty":"MEDIUM","options":[{"id":"a","text":"(1;8)"},{"id":"b","text":"(3;4)"},{"id":"c","text":"(−3;−4)"}],"correctOptionId":"b","explanation":"(2−(−1);6−2)=(3;4)."},{"id":"math-10-coordinate-line-q1","prompt":"Trong ax+by+c=0, một vectơ pháp tuyến là?","difficulty":"EASY","options":[{"id":"a","text":"(c;0)"},{"id":"b","text":"(a;b)"},{"id":"c","text":"(−b;a) luôn là pháp tuyến"}],"correctOptionId":"b","explanation":"Các hệ số của x,y tạo vectơ vuông góc với đường thẳng."},{"id":"math-10-coordinate-line-q2","prompt":"Điểm (1;1) có thuộc đường thẳng x+y−2=0 không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Có"},{"id":"b","text":"Không"},{"id":"c","text":"Chỉ khi x=0"}],"correctOptionId":"a","explanation":"Thay vào: 1+1−2=0."},{"id":"math-10-counting-q1","prompt":"Chọn áo rồi chọn quần là các bước nối tiếp, thường dùng quy tắc nào?","difficulty":"EASY","options":[{"id":"a","text":"Quy tắc nhân"},{"id":"b","text":"Quy tắc cộng"},{"id":"c","text":"Quy tắc trừ"}],"correctOptionId":"a","explanation":"Mỗi kết quả gồm một lựa chọn ở mỗi bước nên nhân số cách."},{"id":"math-10-counting-q2","prompt":"Có 4 món tráng miệng hoặc 3 loại nước, chọn đúng một món. Có bao nhiêu cách?","difficulty":"MEDIUM","options":[{"id":"a","text":"12"},{"id":"b","text":"1"},{"id":"c","text":"7"}],"correctOptionId":"c","explanation":"Hai nhóm lựa chọn loại trừ nhau nên cộng 4+3."},{"id":"math-10-combinations-q1","prompt":"Chọn một ban gồm 3 bạn từ 8 bạn, không phân chức vụ, dùng dạng nào?","difficulty":"EASY","options":[{"id":"a","text":"Hoán vị"},{"id":"b","text":"Chỉnh hợp có lặp"},{"id":"c","text":"Tổ hợp"}],"correctOptionId":"c","explanation":"Không phân chức vụ nên thứ tự chọn không tạo nhóm mới."},{"id":"math-10-combinations-q2","prompt":"C(5,2) bằng?","difficulty":"MEDIUM","options":[{"id":"a","text":"5"},{"id":"b","text":"10"},{"id":"c","text":"20"}],"correctOptionId":"b","explanation":"5·4/(2·1)=10."},{"id":"math-10-statistics-q1","prompt":"Khoảng biến thiên bằng gì?","difficulty":"EASY","options":[{"id":"a","text":"Giá trị ở giữa"},{"id":"b","text":"Giá trị lớn nhất trừ nhỏ nhất"},{"id":"c","text":"Tổng chia số phần tử"}],"correctOptionId":"b","explanation":"Khoảng biến thiên đo độ rộng từ đầu nhỏ đến đầu lớn."},{"id":"math-10-statistics-q2","prompt":"Trung vị của 1,4,7 là?","difficulty":"MEDIUM","options":[{"id":"a","text":"4"},{"id":"b","text":"1"},{"id":"c","text":"7"}],"correctOptionId":"a","explanation":"Dãy đã sắp xếp có phần tử chính giữa là 4."}]'::jsonb, '["math-10-coordinates-vectors","math-10-coordinate-line","math-10-counting","math-10-combinations","math-10-statistics"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'placement', 0, 'PLACEMENT', 'Khảo sát đầu vào', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"literature-10-reading-purpose-q1","prompt":"Bước nào giúp đọc có trọng tâm?","difficulty":"EASY","options":[{"id":"a","text":"Xác định yêu cầu và kiểu văn bản"},{"id":"b","text":"Đọc lướt rồi đoán"},{"id":"c","text":"Chỉ tra nghĩa từng từ"}],"correctOptionId":"a","explanation":"Mục tiêu đọc quyết định thông tin và dấu hiệu cần chú ý."},{"id":"literature-10-reading-purpose-q2","prompt":"Câu hỏi yêu cầu tìm luận điểm chính thì nên ưu tiên điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Một chi tiết ngẫu nhiên"},{"id":"b","text":"Từ dài nhất"},{"id":"c","text":"Ý xuyên suốt được các ý khác hỗ trợ"}],"correctOptionId":"c","explanation":"Luận điểm chính bao quát lập luận, không phải chi tiết đơn lẻ."},{"id":"literature-10-narrative-elements-q1","prompt":"Chi tiết nào thường giúp nhận xét tính cách nhân vật có căn cứ?","difficulty":"EASY","options":[{"id":"a","text":"Màu bìa sách"},{"id":"b","text":"Số trang"},{"id":"c","text":"Hành động, lời nói và lựa chọn"}],"correctOptionId":"c","explanation":"Đặc điểm nhân vật cần dựa vào biểu hiện trong văn bản."},{"id":"literature-10-narrative-elements-q2","prompt":"Cốt truyện chủ yếu là gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Phần chú giải"},{"id":"b","text":"Chuỗi sự kiện được tổ chức trong tác phẩm"},{"id":"c","text":"Danh sách tác giả"}],"correctOptionId":"b","explanation":"Cốt truyện liên kết các biến cố và quan hệ giữa chúng."},{"id":"literature-10-point-of-view-q1","prompt":"Người kể xưng “tôi” có nhất thiết là tác giả ngoài đời không?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ trong thơ"},{"id":"b","text":"Không"},{"id":"c","text":"Luôn luôn"}],"correctOptionId":"b","explanation":"Người kể là cấu trúc nghệ thuật, có thể là nhân vật hư cấu."},{"id":"literature-10-point-of-view-q2","prompt":"Điểm nhìn ảnh hưởng điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Cách và phạm vi thông tin được kể"},{"id":"b","text":"Khổ giấy in"},{"id":"c","text":"Số chương bắt buộc"}],"correctOptionId":"a","explanation":"Vị trí quan sát quyết định người đọc thấy và biết những gì."},{"id":"literature-10-myth-legend-q1","prompt":"Yếu tố kì ảo trong truyện dân gian thường có tác dụng gì?","difficulty":"EASY","options":[{"id":"a","text":"Thể hiện cách nhìn và ước vọng của cộng đồng"},{"id":"b","text":"Chứng minh sự kiện là tư liệu khoa học"},{"id":"c","text":"Thay thế mọi nhân vật"}],"correctOptionId":"a","explanation":"Kì ảo tạo cách lí giải nghệ thuật, không phải bằng chứng khoa học."},{"id":"literature-10-myth-legend-q2","prompt":"Truyền thuyết thường gắn với yếu tố nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Bảng số liệu khí tượng"},{"id":"b","text":"Hướng dẫn lắp ráp"},{"id":"c","text":"Kí ức cộng đồng về nhân vật hoặc sự kiện"}],"correctOptionId":"c","explanation":"Truyền thuyết lưu giữ cách cộng đồng hình dung quá khứ."},{"id":"literature-10-epic-q1","prompt":"Sử thi thường mở rộng phạm vi câu chuyện tới đâu?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ một mẹo nấu ăn"},{"id":"b","text":"Một bản tin ngắn"},{"id":"c","text":"Cộng đồng và biến cố có ý nghĩa lớn"}],"correctOptionId":"c","explanation":"Sử thi gắn hành động anh hùng với số phận cộng đồng."},{"id":"literature-10-epic-q2","prompt":"Phóng đại trong sử thi chủ yếu tạo hiệu quả gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Làm mất mọi xung đột"},{"id":"b","text":"Nhấn mạnh tầm vóc nghệ thuật"},{"id":"c","text":"Đưa ra số đo chính xác"}],"correctOptionId":"b","explanation":"Phóng đại là thủ pháp biểu đạt, cần đọc theo quy ước thể loại."}]'::jsonb, '[]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-reading-purpose', 1, 'LESSON', 'Đọc văn bản có mục đích', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Đọc hiểu gồm nhận biết thông tin, phân tích cách biểu đạt và liên hệ có căn cứ. Xác định yêu cầu câu hỏi trước khi chọn dẫn chứng."]'::jsonb, '["Khi câu hỏi hỏi thái độ người viết, tìm từ ngữ đánh giá và giọng điệu thay vì chỉ kể lại sự việc."]'::jsonb, '[{"id":"literature-10-reading-purpose-q1","prompt":"Bước nào giúp đọc có trọng tâm?","difficulty":"EASY","options":[{"id":"a","text":"Xác định yêu cầu và kiểu văn bản"},{"id":"b","text":"Đọc lướt rồi đoán"},{"id":"c","text":"Chỉ tra nghĩa từng từ"}],"correctOptionId":"a","explanation":"Mục tiêu đọc quyết định thông tin và dấu hiệu cần chú ý."},{"id":"literature-10-reading-purpose-q2","prompt":"Câu hỏi yêu cầu tìm luận điểm chính thì nên ưu tiên điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Một chi tiết ngẫu nhiên"},{"id":"b","text":"Từ dài nhất"},{"id":"c","text":"Ý xuyên suốt được các ý khác hỗ trợ"}],"correctOptionId":"c","explanation":"Luận điểm chính bao quát lập luận, không phải chi tiết đơn lẻ."},{"id":"literature-10-reading-purpose-q3","prompt":"Một bài viết khẳng định công viên giúp cải thiện sức khỏe, rồi nêu số người đi bộ tăng. Số liệu đóng vai trò gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Kết luận chắc chắn cho mọi thành phố"},{"id":"b","text":"Dẫn chứng hỗ trợ luận điểm"},{"id":"c","text":"Nhan đề"}],"correctOptionId":"b","explanation":"Số liệu minh họa lập luận nhưng cần xem nguồn và phạm vi trước khi khái quát."}]'::jsonb, '["literature-10-reading-purpose"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-narrative-elements', 2, 'LESSON', 'Nhân vật, sự kiện và cốt truyện', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Cốt truyện tổ chức các sự kiện; nhân vật bộc lộ tính cách qua hành động, lời nói và lựa chọn. Không suy ra tính cách chỉ từ một chi tiết thiếu ngữ cảnh."]'::jsonb, '["Nhân vật trả lại ví nhặt được và giải thích vì sao, qua đó thể hiện sự trung thực."]'::jsonb, '[{"id":"literature-10-narrative-elements-q1","prompt":"Chi tiết nào thường giúp nhận xét tính cách nhân vật có căn cứ?","difficulty":"EASY","options":[{"id":"a","text":"Màu bìa sách"},{"id":"b","text":"Số trang"},{"id":"c","text":"Hành động, lời nói và lựa chọn"}],"correctOptionId":"c","explanation":"Đặc điểm nhân vật cần dựa vào biểu hiện trong văn bản."},{"id":"literature-10-narrative-elements-q2","prompt":"Cốt truyện chủ yếu là gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Phần chú giải"},{"id":"b","text":"Chuỗi sự kiện được tổ chức trong tác phẩm"},{"id":"c","text":"Danh sách tác giả"}],"correctOptionId":"b","explanation":"Cốt truyện liên kết các biến cố và quan hệ giữa chúng."},{"id":"literature-10-narrative-elements-q3","prompt":"Nhân vật nhiều lần giữ lời hứa dù gặp khó khăn. Nhận xét phù hợp nhất là?","difficulty":"APPLIED","options":[{"id":"a","text":"Có trách nhiệm; cần dẫn các lần thực hiện lời hứa"},{"id":"b","text":"Chắc chắn giàu có"},{"id":"c","text":"Không cần trích chi tiết"}],"correctOptionId":"a","explanation":"Kết luận nên bám vào hành động lặp lại và nêu bằng chứng cụ thể."}]'::jsonb, '["literature-10-narrative-elements"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-point-of-view', 3, 'LESSON', 'Người kể chuyện và điểm nhìn', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Người kể chuyện là tiếng nói kể lại câu chuyện; điểm nhìn cho biết sự việc được quan sát từ vị trí nào. Hai yếu tố này ảnh hưởng lượng thông tin người đọc nhận được."]'::jsonb, '["Người kể xưng “tôi” thường giới hạn điều mình trực tiếp biết, không tự động đồng nghĩa tác giả."]'::jsonb, '[{"id":"literature-10-point-of-view-q1","prompt":"Người kể xưng “tôi” có nhất thiết là tác giả ngoài đời không?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ trong thơ"},{"id":"b","text":"Không"},{"id":"c","text":"Luôn luôn"}],"correctOptionId":"b","explanation":"Người kể là cấu trúc nghệ thuật, có thể là nhân vật hư cấu."},{"id":"literature-10-point-of-view-q2","prompt":"Điểm nhìn ảnh hưởng điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Cách và phạm vi thông tin được kể"},{"id":"b","text":"Khổ giấy in"},{"id":"c","text":"Số chương bắt buộc"}],"correctOptionId":"a","explanation":"Vị trí quan sát quyết định người đọc thấy và biết những gì."},{"id":"literature-10-point-of-view-q3","prompt":"Người kể chỉ biết suy nghĩ của nhân vật chính. Đây là dấu hiệu gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Người kể biết mọi việc"},{"id":"b","text":"Văn bản không có người kể"},{"id":"c","text":"Điểm nhìn giới hạn theo nhân vật"}],"correctOptionId":"c","explanation":"Thông tin bị giới hạn vào trải nghiệm của nhân vật ấy."}]'::jsonb, '["literature-10-point-of-view"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-myth-legend', 4, 'LESSON', 'Đọc truyện thần thoại và truyền thuyết', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Truyện thần thoại thường lí giải nguồn gốc thế giới hoặc hiện tượng bằng tưởng tượng; truyền thuyết gắn với nhân vật, sự kiện được cộng đồng ghi nhớ và yếu tố kì ảo."]'::jsonb, '["Khi đọc truyện về nguồn gốc một dòng sông, phân biệt điều văn bản tưởng tượng với kiến thức khoa học hiện nay."]'::jsonb, '[{"id":"literature-10-myth-legend-q1","prompt":"Yếu tố kì ảo trong truyện dân gian thường có tác dụng gì?","difficulty":"EASY","options":[{"id":"a","text":"Thể hiện cách nhìn và ước vọng của cộng đồng"},{"id":"b","text":"Chứng minh sự kiện là tư liệu khoa học"},{"id":"c","text":"Thay thế mọi nhân vật"}],"correctOptionId":"a","explanation":"Kì ảo tạo cách lí giải nghệ thuật, không phải bằng chứng khoa học."},{"id":"literature-10-myth-legend-q2","prompt":"Truyền thuyết thường gắn với yếu tố nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Bảng số liệu khí tượng"},{"id":"b","text":"Hướng dẫn lắp ráp"},{"id":"c","text":"Kí ức cộng đồng về nhân vật hoặc sự kiện"}],"correctOptionId":"c","explanation":"Truyền thuyết lưu giữ cách cộng đồng hình dung quá khứ."},{"id":"literature-10-myth-legend-q3","prompt":"Khi so sánh truyện sáng thế với kiến thức khoa học, cách đọc phù hợp là?","difficulty":"APPLIED","options":[{"id":"a","text":"Dùng tình tiết làm chứng cứ thực nghiệm"},{"id":"b","text":"Nhận diện chức năng biểu tượng và không coi đó là mô hình khoa học"},{"id":"c","text":"Bác bỏ mọi giá trị văn hóa"}],"correctOptionId":"b","explanation":"Đọc thể loại đúng chức năng giúp vừa hiểu văn hóa vừa tránh nhầm lẫn."}]'::jsonb, '["literature-10-myth-legend"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-epic', 5, 'LESSON', 'Đặc trưng sử thi', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Sử thi thường kể cộng đồng và người anh hùng trong không gian rộng lớn, giọng điệu trang trọng; phóng đại nghệ thuật làm nổi bật tầm vóc chứ không phải phép đo thực tế."]'::jsonb, '["Một hành trình gian nan được kể qua nhiều thử thách để biểu đạt khát vọng và giá trị của cộng đồng."]'::jsonb, '[{"id":"literature-10-epic-q1","prompt":"Sử thi thường mở rộng phạm vi câu chuyện tới đâu?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ một mẹo nấu ăn"},{"id":"b","text":"Một bản tin ngắn"},{"id":"c","text":"Cộng đồng và biến cố có ý nghĩa lớn"}],"correctOptionId":"c","explanation":"Sử thi gắn hành động anh hùng với số phận cộng đồng."},{"id":"literature-10-epic-q2","prompt":"Phóng đại trong sử thi chủ yếu tạo hiệu quả gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Làm mất mọi xung đột"},{"id":"b","text":"Nhấn mạnh tầm vóc nghệ thuật"},{"id":"c","text":"Đưa ra số đo chính xác"}],"correctOptionId":"b","explanation":"Phóng đại là thủ pháp biểu đạt, cần đọc theo quy ước thể loại."},{"id":"literature-10-epic-q3","prompt":"Khi phân tích người anh hùng, nên kết hợp hành động cá nhân với điều gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Giá trị và ước vọng cộng đồng"},{"id":"b","text":"Giá bán sách"},{"id":"c","text":"Số lần xuống dòng"}],"correctOptionId":"a","explanation":"Nhân vật sử thi thường đại diện những chuẩn mực và khát vọng chung."}]'::jsonb, '["literature-10-epic"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-review-1', 6, 'FIVE_LESSON_REVIEW', 'Ôn tập 1', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"literature-10-reading-purpose-q1","prompt":"Bước nào giúp đọc có trọng tâm?","difficulty":"EASY","options":[{"id":"a","text":"Xác định yêu cầu và kiểu văn bản"},{"id":"b","text":"Đọc lướt rồi đoán"},{"id":"c","text":"Chỉ tra nghĩa từng từ"}],"correctOptionId":"a","explanation":"Mục tiêu đọc quyết định thông tin và dấu hiệu cần chú ý."},{"id":"literature-10-reading-purpose-q2","prompt":"Câu hỏi yêu cầu tìm luận điểm chính thì nên ưu tiên điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Một chi tiết ngẫu nhiên"},{"id":"b","text":"Từ dài nhất"},{"id":"c","text":"Ý xuyên suốt được các ý khác hỗ trợ"}],"correctOptionId":"c","explanation":"Luận điểm chính bao quát lập luận, không phải chi tiết đơn lẻ."},{"id":"literature-10-narrative-elements-q1","prompt":"Chi tiết nào thường giúp nhận xét tính cách nhân vật có căn cứ?","difficulty":"EASY","options":[{"id":"a","text":"Màu bìa sách"},{"id":"b","text":"Số trang"},{"id":"c","text":"Hành động, lời nói và lựa chọn"}],"correctOptionId":"c","explanation":"Đặc điểm nhân vật cần dựa vào biểu hiện trong văn bản."},{"id":"literature-10-narrative-elements-q2","prompt":"Cốt truyện chủ yếu là gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Phần chú giải"},{"id":"b","text":"Chuỗi sự kiện được tổ chức trong tác phẩm"},{"id":"c","text":"Danh sách tác giả"}],"correctOptionId":"b","explanation":"Cốt truyện liên kết các biến cố và quan hệ giữa chúng."},{"id":"literature-10-point-of-view-q1","prompt":"Người kể xưng “tôi” có nhất thiết là tác giả ngoài đời không?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ trong thơ"},{"id":"b","text":"Không"},{"id":"c","text":"Luôn luôn"}],"correctOptionId":"b","explanation":"Người kể là cấu trúc nghệ thuật, có thể là nhân vật hư cấu."},{"id":"literature-10-point-of-view-q2","prompt":"Điểm nhìn ảnh hưởng điều gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Cách và phạm vi thông tin được kể"},{"id":"b","text":"Khổ giấy in"},{"id":"c","text":"Số chương bắt buộc"}],"correctOptionId":"a","explanation":"Vị trí quan sát quyết định người đọc thấy và biết những gì."},{"id":"literature-10-myth-legend-q1","prompt":"Yếu tố kì ảo trong truyện dân gian thường có tác dụng gì?","difficulty":"EASY","options":[{"id":"a","text":"Thể hiện cách nhìn và ước vọng của cộng đồng"},{"id":"b","text":"Chứng minh sự kiện là tư liệu khoa học"},{"id":"c","text":"Thay thế mọi nhân vật"}],"correctOptionId":"a","explanation":"Kì ảo tạo cách lí giải nghệ thuật, không phải bằng chứng khoa học."},{"id":"literature-10-myth-legend-q2","prompt":"Truyền thuyết thường gắn với yếu tố nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Bảng số liệu khí tượng"},{"id":"b","text":"Hướng dẫn lắp ráp"},{"id":"c","text":"Kí ức cộng đồng về nhân vật hoặc sự kiện"}],"correctOptionId":"c","explanation":"Truyền thuyết lưu giữ cách cộng đồng hình dung quá khứ."},{"id":"literature-10-epic-q1","prompt":"Sử thi thường mở rộng phạm vi câu chuyện tới đâu?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ một mẹo nấu ăn"},{"id":"b","text":"Một bản tin ngắn"},{"id":"c","text":"Cộng đồng và biến cố có ý nghĩa lớn"}],"correctOptionId":"c","explanation":"Sử thi gắn hành động anh hùng với số phận cộng đồng."},{"id":"literature-10-epic-q2","prompt":"Phóng đại trong sử thi chủ yếu tạo hiệu quả gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Làm mất mọi xung đột"},{"id":"b","text":"Nhấn mạnh tầm vóc nghệ thuật"},{"id":"c","text":"Đưa ra số đo chính xác"}],"correctOptionId":"b","explanation":"Phóng đại là thủ pháp biểu đạt, cần đọc theo quy ước thể loại."}]'::jsonb, '["literature-10-reading-purpose","literature-10-narrative-elements","literature-10-point-of-view","literature-10-myth-legend","literature-10-epic"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-short-story', 7, 'LESSON', 'Đọc truyện ngắn và chi tiết nghệ thuật', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Truyện ngắn cô đọng quanh tình huống và một số chi tiết có sức gợi. Tình huống làm nhân vật bộc lộ phẩm chất hoặc tạo chuyển biến nhận thức."]'::jsonb, '["Một chiếc vé cũ xuất hiện đầu và cuối truyện có thể nối các mốc thời gian, nhưng cần căn cứ cách văn bản dùng nó."]'::jsonb, '[{"id":"literature-10-short-story-q1","prompt":"Tình huống truyện giúp làm rõ điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Số từ trong tựa đề"},{"id":"b","text":"Xung đột và lựa chọn của nhân vật"},{"id":"c","text":"Định dạng trang"}],"correctOptionId":"b","explanation":"Tình huống tạo hoàn cảnh để tính cách và chủ đề hiện ra."},{"id":"literature-10-short-story-q2","prompt":"Chi tiết lặp lại trong truyện có thể tạo tác dụng nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Liên kết ý nghĩa hoặc biến chuyển"},{"id":"b","text":"Bảo đảm truyện là thật"},{"id":"c","text":"Thay cho mọi phân tích"}],"correctOptionId":"a","explanation":"Tác dụng cần được chứng minh bằng vị trí và ngữ cảnh xuất hiện."},{"id":"literature-10-short-story-q3","prompt":"Muốn kết luận một chi tiết biểu tượng cho hi vọng, cần làm gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Chỉ dựa vào màu sắc"},{"id":"b","text":"Tra một nghĩa cố định duy nhất"},{"id":"c","text":"Phân tích ngữ cảnh, sự lặp lại và phản ứng nhân vật"}],"correctOptionId":"c","explanation":"Ý nghĩa biểu tượng hình thành trong quan hệ với toàn văn bản."}]'::jsonb, '["literature-10-short-story"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-poetry-image', 8, 'LESSON', 'Hình ảnh, từ ngữ và cảm xúc trong thơ', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Hình ảnh thơ có thể gợi tả và gợi cảm. Phân tích nên nối từ ngữ cụ thể với cảm xúc, chủ đề và ngữ cảnh, tránh gán ý nghĩa tùy tiện."]'::jsonb, '["Hình ảnh “cánh cửa hé sáng” có thể gợi mở một khởi đầu nếu mạch thơ hỗ trợ cách hiểu ấy."]'::jsonb, '[{"id":"literature-10-poetry-image-q1","prompt":"Phân tích hình ảnh thơ cần dựa vào điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Từ ngữ và mạch văn bản"},{"id":"b","text":"Suy đoán không dẫn chứng"},{"id":"c","text":"Tiểu sử người đọc"}],"correctOptionId":"a","explanation":"Cách hiểu phải có căn cứ trong cách dùng từ và toàn bài."},{"id":"literature-10-poetry-image-q2","prompt":"Một hình ảnh vừa tả cảnh vừa gợi tâm trạng là biểu hiện nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Sai lệch thể loại"},{"id":"b","text":"Bảng thống kê"},{"id":"c","text":"Tính gợi của ngôn ngữ thơ"}],"correctOptionId":"c","explanation":"Thơ thường nén nhiều lớp nghĩa trong hình ảnh."},{"id":"literature-10-poetry-image-q3","prompt":"Nếu cùng một hình ảnh được hiểu theo hai cách khác nhau, em nên làm gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Bỏ qua văn bản"},{"id":"b","text":"Đối chiếu mỗi cách với ngữ cảnh và dẫn chứng"},{"id":"c","text":"Chọn cách nghe hay hơn"}],"correctOptionId":"b","explanation":"Đọc đa nghĩa vẫn cần kiểm tra mức độ phù hợp với văn bản."}]'::jsonb, '["literature-10-poetry-image"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-rhyme-rhythm', 9, 'LESSON', 'Nhịp, vần và âm hưởng', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Vần tạo liên kết âm thanh; nhịp tổ chức chỗ ngắt và tốc độ đọc. Cần đọc thành tiếng hoặc đánh dấu nhịp trước khi nêu tác dụng."]'::jsonb, '["Nhịp ngắn, dồn có thể tạo cảm giác gấp nếu cú pháp và nội dung cùng hướng đó."]'::jsonb, '[{"id":"literature-10-rhyme-rhythm-q1","prompt":"Cách tốt để nhận ra nhịp thơ là?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ đếm chữ cái"},{"id":"b","text":"Đọc nhan đề"},{"id":"c","text":"Đọc thành tiếng và quan sát cú pháp"}],"correctOptionId":"c","explanation":"Nhịp liên quan cách ngắt câu, âm tiết và nhấn giọng."},{"id":"literature-10-rhyme-rhythm-q2","prompt":"Vần thơ tạo liên kết chủ yếu ở phương diện nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Số tác giả"},{"id":"b","text":"Âm thanh"},{"id":"c","text":"Màu sắc trang"}],"correctOptionId":"b","explanation":"Các tiếng hiệp vần tạo sự vang nối trong bài."},{"id":"literature-10-rhyme-rhythm-q3","prompt":"Nhịp thơ nhanh nhưng nội dung đang tả nỗi buồn. Kết luận an toàn là?","difficulty":"APPLIED","options":[{"id":"a","text":"Nêu hiệu quả nhịp trong đoạn và dựa vào từ ngữ cụ thể"},{"id":"b","text":"Nhịp nhanh luôn vui"},{"id":"c","text":"Nhịp không ảnh hưởng cảm xúc"}],"correctOptionId":"a","explanation":"Tác dụng nhịp phụ thuộc văn cảnh, không có quy tắc đơn giản tuyệt đối."}]'::jsonb, '["literature-10-rhyme-rhythm"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-argumentation', 10, 'LESSON', 'Luận đề, luận điểm và lí lẽ', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Văn bản nghị luận nêu luận đề, triển khai bằng luận điểm, lí lẽ và dẫn chứng. Dẫn chứng phù hợp phải liên quan và đủ tin cậy cho kết luận."]'::jsonb, '["Luận đề “nên đọc sách mỗi ngày” có thể được hỗ trợ bằng lí do về vốn từ và ví dụ cụ thể."]'::jsonb, '[{"id":"literature-10-argumentation-q1","prompt":"Luận điểm trong bài nghị luận làm nhiệm vụ gì?","difficulty":"EASY","options":[{"id":"a","text":"Thay mọi dẫn chứng"},{"id":"b","text":"Triển khai và hỗ trợ luận đề"},{"id":"c","text":"Trang trí văn bản"}],"correctOptionId":"b","explanation":"Các luận điểm tổ chức lí do để bảo vệ luận đề."},{"id":"literature-10-argumentation-q2","prompt":"Dẫn chứng tốt cần có đặc điểm nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Liên quan và kiểm chứng được"},{"id":"b","text":"Càng dài càng tốt"},{"id":"c","text":"Không cần nguồn"}],"correctOptionId":"a","explanation":"Độ tin cậy và sự liên quan quyết định sức nặng của dẫn chứng."},{"id":"literature-10-argumentation-q3","prompt":"Một bài lấy một câu chuyện cá nhân để kết luận mọi học sinh đều học tốt khi nghe nhạc. Hạn chế chính là?","difficulty":"APPLIED","options":[{"id":"a","text":"Có quá nhiều luận đề"},{"id":"b","text":"Dùng sai dấu chấm"},{"id":"c","text":"Khái quát vượt quá phạm vi dẫn chứng"}],"correctOptionId":"c","explanation":"Một trường hợp riêng không đủ đại diện cho toàn bộ học sinh."}]'::jsonb, '["literature-10-argumentation"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-information-text', 11, 'LESSON', 'Đọc văn bản thông tin', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Văn bản thông tin trình bày dữ kiện, giải thích hoặc hướng dẫn. Phân biệt dữ kiện với nhận định; chú ý nguồn, thời điểm, đơn vị và phạm vi khảo sát."]'::jsonb, '["Tỉ lệ 40% chỉ có nghĩa khi biết 40% của nhóm nào, trong thời gian và cách đo nào."]'::jsonb, '[{"id":"literature-10-information-text-q1","prompt":"Khi đọc một con số phần trăm, cần hỏi thêm điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Mẫu số, phạm vi và thời điểm"},{"id":"b","text":"Màu chữ"},{"id":"c","text":"Số đoạn văn"}],"correctOptionId":"a","explanation":"Tỉ lệ cần có mẫu số và ngữ cảnh mới diễn giải được."},{"id":"literature-10-information-text-q2","prompt":"Dữ kiện khác nhận định ở điểm nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Dữ kiện luôn sai"},{"id":"b","text":"Nhận định luôn là số"},{"id":"c","text":"Dữ kiện có thể kiểm tra; nhận định là đánh giá hoặc diễn giải"}],"correctOptionId":"c","explanation":"Phân biệt hai loại giúp không coi ý kiến là sự thật đã chứng minh."},{"id":"literature-10-information-text-q3","prompt":"Bài đăng trích số liệu nhưng không ghi nguồn. Cách xử lí phù hợp là?","difficulty":"APPLIED","options":[{"id":"a","text":"Tự thêm nguồn"},{"id":"b","text":"Tạm thận trọng và tìm nguồn gốc dữ liệu"},{"id":"c","text":"Chia sẻ ngay như sự thật"}],"correctOptionId":"b","explanation":"Không có nguồn làm giảm khả năng kiểm chứng."}]'::jsonb, '["literature-10-information-text"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-review-2', 12, 'FIVE_LESSON_REVIEW', 'Ôn tập 2', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"literature-10-short-story-q1","prompt":"Tình huống truyện giúp làm rõ điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Số từ trong tựa đề"},{"id":"b","text":"Xung đột và lựa chọn của nhân vật"},{"id":"c","text":"Định dạng trang"}],"correctOptionId":"b","explanation":"Tình huống tạo hoàn cảnh để tính cách và chủ đề hiện ra."},{"id":"literature-10-short-story-q2","prompt":"Chi tiết lặp lại trong truyện có thể tạo tác dụng nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Liên kết ý nghĩa hoặc biến chuyển"},{"id":"b","text":"Bảo đảm truyện là thật"},{"id":"c","text":"Thay cho mọi phân tích"}],"correctOptionId":"a","explanation":"Tác dụng cần được chứng minh bằng vị trí và ngữ cảnh xuất hiện."},{"id":"literature-10-poetry-image-q1","prompt":"Phân tích hình ảnh thơ cần dựa vào điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Từ ngữ và mạch văn bản"},{"id":"b","text":"Suy đoán không dẫn chứng"},{"id":"c","text":"Tiểu sử người đọc"}],"correctOptionId":"a","explanation":"Cách hiểu phải có căn cứ trong cách dùng từ và toàn bài."},{"id":"literature-10-poetry-image-q2","prompt":"Một hình ảnh vừa tả cảnh vừa gợi tâm trạng là biểu hiện nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Sai lệch thể loại"},{"id":"b","text":"Bảng thống kê"},{"id":"c","text":"Tính gợi của ngôn ngữ thơ"}],"correctOptionId":"c","explanation":"Thơ thường nén nhiều lớp nghĩa trong hình ảnh."},{"id":"literature-10-rhyme-rhythm-q1","prompt":"Cách tốt để nhận ra nhịp thơ là?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ đếm chữ cái"},{"id":"b","text":"Đọc nhan đề"},{"id":"c","text":"Đọc thành tiếng và quan sát cú pháp"}],"correctOptionId":"c","explanation":"Nhịp liên quan cách ngắt câu, âm tiết và nhấn giọng."},{"id":"literature-10-rhyme-rhythm-q2","prompt":"Vần thơ tạo liên kết chủ yếu ở phương diện nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Số tác giả"},{"id":"b","text":"Âm thanh"},{"id":"c","text":"Màu sắc trang"}],"correctOptionId":"b","explanation":"Các tiếng hiệp vần tạo sự vang nối trong bài."},{"id":"literature-10-argumentation-q1","prompt":"Luận điểm trong bài nghị luận làm nhiệm vụ gì?","difficulty":"EASY","options":[{"id":"a","text":"Thay mọi dẫn chứng"},{"id":"b","text":"Triển khai và hỗ trợ luận đề"},{"id":"c","text":"Trang trí văn bản"}],"correctOptionId":"b","explanation":"Các luận điểm tổ chức lí do để bảo vệ luận đề."},{"id":"literature-10-argumentation-q2","prompt":"Dẫn chứng tốt cần có đặc điểm nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Liên quan và kiểm chứng được"},{"id":"b","text":"Càng dài càng tốt"},{"id":"c","text":"Không cần nguồn"}],"correctOptionId":"a","explanation":"Độ tin cậy và sự liên quan quyết định sức nặng của dẫn chứng."},{"id":"literature-10-information-text-q1","prompt":"Khi đọc một con số phần trăm, cần hỏi thêm điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Mẫu số, phạm vi và thời điểm"},{"id":"b","text":"Màu chữ"},{"id":"c","text":"Số đoạn văn"}],"correctOptionId":"a","explanation":"Tỉ lệ cần có mẫu số và ngữ cảnh mới diễn giải được."},{"id":"literature-10-information-text-q2","prompt":"Dữ kiện khác nhận định ở điểm nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Dữ kiện luôn sai"},{"id":"b","text":"Nhận định luôn là số"},{"id":"c","text":"Dữ kiện có thể kiểm tra; nhận định là đánh giá hoặc diễn giải"}],"correctOptionId":"c","explanation":"Phân biệt hai loại giúp không coi ý kiến là sự thật đã chứng minh."}]'::jsonb, '["literature-10-short-story","literature-10-poetry-image","literature-10-rhyme-rhythm","literature-10-argumentation","literature-10-information-text"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-paragraph-cohesion', 13, 'LESSON', 'Đoạn văn và liên kết ý', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Đoạn văn thường có một ý chính được phát triển bằng các câu hỗ trợ. Phép lặp, phép thế, nối và liên tưởng giúp liên kết nhưng cần tránh lặp rườm rà."]'::jsonb, '["Có thể dùng “ý kiến ấy” để thế cho quan điểm vừa nêu, miễn đại từ quy chiếu rõ."]'::jsonb, '[{"id":"literature-10-paragraph-cohesion-q1","prompt":"Một đoạn văn mạch lạc cần điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Mỗi câu nói một chủ đề khác"},{"id":"b","text":"Thật nhiều từ nối"},{"id":"c","text":"Các câu cùng phục vụ ý chính và liên kết rõ"}],"correctOptionId":"c","explanation":"Liên kết không thay thế sự thống nhất nội dung."},{"id":"literature-10-paragraph-cohesion-q2","prompt":"Từ “điều đó” có hiệu quả khi nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Dùng thay mọi danh từ"},{"id":"b","text":"Đối tượng được nhắc tới rõ ràng"},{"id":"c","text":"Không có nội dung trước đó"}],"correctOptionId":"b","explanation":"Từ thế cần có chỗ quy chiếu giúp người đọc hiểu."},{"id":"literature-10-paragraph-cohesion-q3","prompt":"Đoạn văn có ba câu lặp nguyên một ý. Cách sửa tốt là?","difficulty":"APPLIED","options":[{"id":"a","text":"Giữ câu nêu ý, thay câu sau bằng lí giải hoặc dẫn chứng"},{"id":"b","text":"Thêm nhiều từ nối"},{"id":"c","text":"Xóa dấu câu"}],"correctOptionId":"a","explanation":"Mỗi câu nên đóng góp một bước phát triển ý."}]'::jsonb, '["literature-10-paragraph-cohesion"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-figurative-language', 14, 'LESSON', 'Biện pháp tu từ và tác dụng', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["So sánh, nhân hóa, ẩn dụ và điệp ngữ tạo hình ảnh hoặc nhấn mạnh. Gọi đúng tên biện pháp chưa đủ; cần nêu tác dụng trong câu cụ thể."]'::jsonb, '["“Gió thì thầm” nhân hóa gió và có thể gợi âm thanh nhẹ nếu đoạn văn phù hợp."]'::jsonb, '[{"id":"literature-10-figurative-language-q1","prompt":"“Mặt trời xuống biển như hòn lửa” nổi bật biện pháp nào?","difficulty":"EASY","options":[{"id":"a","text":"Nói giảm"},{"id":"b","text":"So sánh"},{"id":"c","text":"Liệt kê"}],"correctOptionId":"b","explanation":"Từ “như” nối hai hình ảnh có nét tương đồng."},{"id":"literature-10-figurative-language-q2","prompt":"Sau khi gọi tên phép tu từ, cần làm gì tiếp?","difficulty":"MEDIUM","options":[{"id":"a","text":"Chỉ ra từ ngữ và hiệu quả trong ngữ cảnh"},{"id":"b","text":"Lặp lại định nghĩa"},{"id":"c","text":"Kết luận chung chung"}],"correctOptionId":"a","explanation":"Tác dụng phải gắn với hình ảnh, cảm xúc hoặc ý nghĩa cụ thể."},{"id":"literature-10-figurative-language-q3","prompt":"Một câu lặp “mãi” nhiều lần để nhấn nỗi chờ đợi. Nhận xét nào hợp lí?","difficulty":"APPLIED","options":[{"id":"a","text":"Điệp từ chứng minh thời gian chính xác"},{"id":"b","text":"Không thể tạo tác dụng"},{"id":"c","text":"Điệp từ làm nổi bật cảm giác kéo dài"}],"correctOptionId":"c","explanation":"Sự lặp có thể nhấn mạnh trạng thái nhưng không thay thế dữ kiện thời gian."}]'::jsonb, '["literature-10-figurative-language"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-sentence-structure', 15, 'LESSON', 'Câu, thành phần và dấu câu', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Chủ ngữ nêu đối tượng; vị ngữ nêu hoạt động, trạng thái hoặc đặc điểm. Dấu câu giúp biểu thị quan hệ và nhịp; cần đọc lại để phát hiện câu thiếu thành phần."]'::jsonb, '["“Sau cơn mưa, sân trường sáng lên.” có trạng ngữ thời gian, chủ ngữ “sân trường” và vị ngữ “sáng lên”."]'::jsonb, '[{"id":"literature-10-sentence-structure-q1","prompt":"Trong câu “Sân trường sáng lên”, chủ ngữ là?","difficulty":"EASY","options":[{"id":"a","text":"Sân trường"},{"id":"b","text":"Sáng lên"},{"id":"c","text":"Lên"}],"correctOptionId":"a","explanation":"Chủ ngữ nêu đối tượng được nói đến."},{"id":"literature-10-sentence-structure-q2","prompt":"Dấu phẩy trong câu thường có tác dụng nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Luôn thay dấu chấm"},{"id":"b","text":"Bảo đảm câu đúng dù thiếu ý"},{"id":"c","text":"Đánh dấu ranh giới hoặc thành phần phụ theo cấu trúc"}],"correctOptionId":"c","explanation":"Dấu câu phải phù hợp cấu trúc, không tự sửa câu thiếu thành phần."},{"id":"literature-10-sentence-structure-q3","prompt":"Câu “Khi em đến thư viện.” đứng riêng thường tạo cảm giác gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Là câu hỏi"},{"id":"b","text":"Thiếu mệnh đề chính"},{"id":"c","text":"Đủ chủ-vị hoàn chỉnh"}],"correctOptionId":"b","explanation":"Mệnh đề bắt đầu bằng “khi” thường cần phần nêu sự việc chính."}]'::jsonb, '["literature-10-sentence-structure"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-analytical-writing', 16, 'LESSON', 'Viết đoạn phân tích văn học', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Đoạn phân tích cần luận điểm rõ, dẫn chứng chính xác và phần lí giải nối dẫn chứng với luận điểm. Tránh kể lại toàn bộ tác phẩm."]'::jsonb, '["Luận điểm về sự trưởng thành của nhân vật có thể dẫn một lựa chọn then chốt rồi phân tích hệ quả."]'::jsonb, '[{"id":"literature-10-analytical-writing-q1","prompt":"Dẫn chứng trong đoạn phân tích cần đi kèm điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Một nhận xét không căn cứ"},{"id":"b","text":"Tóm tắt toàn truyện"},{"id":"c","text":"Lí giải mối liên hệ với luận điểm"}],"correctOptionId":"c","explanation":"Dẫn chứng chỉ thuyết phục khi được diễn giải."},{"id":"literature-10-analytical-writing-q2","prompt":"Mục đích của luận điểm đầu đoạn là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Giới thiệu số trang"},{"id":"b","text":"Nêu nhận xét cần chứng minh"},{"id":"c","text":"Kể hết cốt truyện"}],"correctOptionId":"b","explanation":"Luận điểm định hướng các dẫn chứng và phân tích tiếp theo."},{"id":"literature-10-analytical-writing-q3","prompt":"Đoạn viết chỉ tóm tắt ba sự kiện, chưa phân tích. Nên bổ sung gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Nhận xét về ý nghĩa chi tiết và cách thể hiện"},{"id":"b","text":"Thêm sự kiện thứ tư"},{"id":"c","text":"Thêm lời khen chung"}],"correctOptionId":"a","explanation":"Phân tích làm rõ vì sao chi tiết hỗ trợ nhận định."}]'::jsonb, '["literature-10-analytical-writing"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-speaking-listening', 17, 'LESSON', 'Nói, nghe và phản hồi có căn cứ', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Bài trình bày hiệu quả có mục tiêu, thứ tự ý và ví dụ vừa đủ. Khi phản hồi, nhắc lại chính xác ý bạn, nêu điểm đồng thuận hoặc câu hỏi, giữ thái độ tôn trọng."]'::jsonb, '["“Mình hiểu bạn cho rằng…; bạn có thể giải thích thêm dữ kiện…” vừa xác nhận vừa mở đối thoại."]'::jsonb, '[{"id":"literature-10-speaking-listening-q1","prompt":"Trước khi phản biện, nên làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Gán động cơ"},{"id":"b","text":"Hiểu và diễn đạt lại đúng ý người nói"},{"id":"c","text":"Ngắt lời ngay"}],"correctOptionId":"b","explanation":"Lắng nghe chính xác giúp phản hồi vào luận điểm thật."},{"id":"literature-10-speaking-listening-q2","prompt":"Bài nói có bố cục nào dễ theo dõi?","difficulty":"MEDIUM","options":[{"id":"a","text":"Mở ý, triển khai, kết luận"},{"id":"b","text":"Các ý hoàn toàn ngẫu nhiên"},{"id":"c","text":"Chỉ đọc nguyên slide"}],"correctOptionId":"a","explanation":"Trình tự rõ giúp người nghe theo dõi mạch lập luận."},{"id":"literature-10-speaking-listening-q3","prompt":"Bạn không đồng ý với ý kiến của bạn học. Cách phản hồi tốt là?","difficulty":"APPLIED","options":[{"id":"a","text":"Chê người nói"},{"id":"b","text":"Khẳng định mình đúng mà không giải thích"},{"id":"c","text":"Nêu lí do và bằng chứng, đồng thời giữ lời lẽ tôn trọng"}],"correctOptionId":"c","explanation":"Phản biện nên tập trung vào lập luận và có căn cứ."}]'::jsonb, '["literature-10-speaking-listening"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('literature', 10, 'intro-2026.1', 'literature-10-review-3', 18, 'FIVE_LESSON_REVIEW', 'Ôn tập 3', 'Ngữ văn: đọc hiểu, tiếng Việt và tạo lập văn bản', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"literature-10-paragraph-cohesion-q1","prompt":"Một đoạn văn mạch lạc cần điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Mỗi câu nói một chủ đề khác"},{"id":"b","text":"Thật nhiều từ nối"},{"id":"c","text":"Các câu cùng phục vụ ý chính và liên kết rõ"}],"correctOptionId":"c","explanation":"Liên kết không thay thế sự thống nhất nội dung."},{"id":"literature-10-paragraph-cohesion-q2","prompt":"Từ “điều đó” có hiệu quả khi nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Dùng thay mọi danh từ"},{"id":"b","text":"Đối tượng được nhắc tới rõ ràng"},{"id":"c","text":"Không có nội dung trước đó"}],"correctOptionId":"b","explanation":"Từ thế cần có chỗ quy chiếu giúp người đọc hiểu."},{"id":"literature-10-figurative-language-q1","prompt":"“Mặt trời xuống biển như hòn lửa” nổi bật biện pháp nào?","difficulty":"EASY","options":[{"id":"a","text":"Nói giảm"},{"id":"b","text":"So sánh"},{"id":"c","text":"Liệt kê"}],"correctOptionId":"b","explanation":"Từ “như” nối hai hình ảnh có nét tương đồng."},{"id":"literature-10-figurative-language-q2","prompt":"Sau khi gọi tên phép tu từ, cần làm gì tiếp?","difficulty":"MEDIUM","options":[{"id":"a","text":"Chỉ ra từ ngữ và hiệu quả trong ngữ cảnh"},{"id":"b","text":"Lặp lại định nghĩa"},{"id":"c","text":"Kết luận chung chung"}],"correctOptionId":"a","explanation":"Tác dụng phải gắn với hình ảnh, cảm xúc hoặc ý nghĩa cụ thể."},{"id":"literature-10-sentence-structure-q1","prompt":"Trong câu “Sân trường sáng lên”, chủ ngữ là?","difficulty":"EASY","options":[{"id":"a","text":"Sân trường"},{"id":"b","text":"Sáng lên"},{"id":"c","text":"Lên"}],"correctOptionId":"a","explanation":"Chủ ngữ nêu đối tượng được nói đến."},{"id":"literature-10-sentence-structure-q2","prompt":"Dấu phẩy trong câu thường có tác dụng nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Luôn thay dấu chấm"},{"id":"b","text":"Bảo đảm câu đúng dù thiếu ý"},{"id":"c","text":"Đánh dấu ranh giới hoặc thành phần phụ theo cấu trúc"}],"correctOptionId":"c","explanation":"Dấu câu phải phù hợp cấu trúc, không tự sửa câu thiếu thành phần."},{"id":"literature-10-analytical-writing-q1","prompt":"Dẫn chứng trong đoạn phân tích cần đi kèm điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Một nhận xét không căn cứ"},{"id":"b","text":"Tóm tắt toàn truyện"},{"id":"c","text":"Lí giải mối liên hệ với luận điểm"}],"correctOptionId":"c","explanation":"Dẫn chứng chỉ thuyết phục khi được diễn giải."},{"id":"literature-10-analytical-writing-q2","prompt":"Mục đích của luận điểm đầu đoạn là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Giới thiệu số trang"},{"id":"b","text":"Nêu nhận xét cần chứng minh"},{"id":"c","text":"Kể hết cốt truyện"}],"correctOptionId":"b","explanation":"Luận điểm định hướng các dẫn chứng và phân tích tiếp theo."},{"id":"literature-10-speaking-listening-q1","prompt":"Trước khi phản biện, nên làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Gán động cơ"},{"id":"b","text":"Hiểu và diễn đạt lại đúng ý người nói"},{"id":"c","text":"Ngắt lời ngay"}],"correctOptionId":"b","explanation":"Lắng nghe chính xác giúp phản hồi vào luận điểm thật."},{"id":"literature-10-speaking-listening-q2","prompt":"Bài nói có bố cục nào dễ theo dõi?","difficulty":"MEDIUM","options":[{"id":"a","text":"Mở ý, triển khai, kết luận"},{"id":"b","text":"Các ý hoàn toàn ngẫu nhiên"},{"id":"c","text":"Chỉ đọc nguyên slide"}],"correctOptionId":"a","explanation":"Trình tự rõ giúp người nghe theo dõi mạch lập luận."}]'::jsonb, '["literature-10-paragraph-cohesion","literature-10-figurative-language","literature-10-sentence-structure","literature-10-analytical-writing","literature-10-speaking-listening"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'placement', 0, 'PLACEMENT', 'Khảo sát đầu vào', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"english-10-present-simple-q1","prompt":"Choose the correct form: He ___ to school by bus.","difficulty":"EASY","options":[{"id":"a","text":"goes"},{"id":"b","text":"go"},{"id":"c","text":"going"}],"correctOptionId":"a","explanation":"He is third-person singular, so the verb takes -es."},{"id":"english-10-present-simple-q2","prompt":"Which sentence describes a routine?","difficulty":"MEDIUM","options":[{"id":"a","text":"I am reading right now."},{"id":"b","text":"I read a book yesterday."},{"id":"c","text":"I read for twenty minutes every night."}],"correctOptionId":"c","explanation":"“Every night” signals a repeated habit."},{"id":"english-10-present-continuous-q1","prompt":"Present continuous uses which structure?","difficulty":"EASY","options":[{"id":"a","text":"do/does + base verb"},{"id":"b","text":"will + verb-ing"},{"id":"c","text":"am/is/are + verb-ing"}],"correctOptionId":"c","explanation":"The auxiliary be is followed by the -ing form."},{"id":"english-10-present-continuous-q2","prompt":"Look! The children ___ in the yard.","difficulty":"MEDIUM","options":[{"id":"a","text":"played"},{"id":"b","text":"are playing"},{"id":"c","text":"play"}],"correctOptionId":"b","explanation":"“Look!” points to an action happening now."},{"id":"english-10-past-simple-q1","prompt":"Choose the past form of “go”.","difficulty":"EASY","options":[{"id":"a","text":"gone"},{"id":"b","text":"went"},{"id":"c","text":"goed"}],"correctOptionId":"b","explanation":"“Went” is the simple past form; “gone” is the past participle."},{"id":"english-10-past-simple-q2","prompt":"They ___ the clean-up event yesterday.","difficulty":"MEDIUM","options":[{"id":"a","text":"joined"},{"id":"b","text":"join"},{"id":"c","text":"are join"}],"correctOptionId":"a","explanation":"“Yesterday” calls for the past simple."},{"id":"english-10-future-plans-q1","prompt":"Complete: I ___ going to call my teacher.","difficulty":"EASY","options":[{"id":"a","text":"am"},{"id":"b","text":"is"},{"id":"c","text":"are"}],"correctOptionId":"a","explanation":"Use am with I."},{"id":"english-10-future-plans-q2","prompt":"Which sentence expresses a prior plan?","difficulty":"MEDIUM","options":[{"id":"a","text":"They visited it last week."},{"id":"b","text":"They visit it every Monday."},{"id":"c","text":"They are going to visit the science fair tomorrow."}],"correctOptionId":"c","explanation":"“Be going to” presents a plan for the future."},{"id":"english-10-countable-uncountable-q1","prompt":"Which noun is normally uncountable?","difficulty":"EASY","options":[{"id":"a","text":"apple"},{"id":"b","text":"notebook"},{"id":"c","text":"water"}],"correctOptionId":"c","explanation":"Water is generally treated as an uncountable noun."},{"id":"english-10-countable-uncountable-q2","prompt":"Choose the natural phrase.","difficulty":"MEDIUM","options":[{"id":"a","text":"three informations"},{"id":"b","text":"some information"},{"id":"c","text":"an information"}],"correctOptionId":"b","explanation":"Information is uncountable in standard English."}]'::jsonb, '[]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-present-simple', 1, 'LESSON', 'Present simple và thói quen', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Dùng hiện tại đơn cho thói quen, sự thật chung và lịch cố định. Với he/she/it, động từ thường thêm -s/-es ở câu khẳng định."]'::jsonb, '["She studies English every evening. They study together on Fridays."]'::jsonb, '[{"id":"english-10-present-simple-q1","prompt":"Choose the correct form: He ___ to school by bus.","difficulty":"EASY","options":[{"id":"a","text":"goes"},{"id":"b","text":"go"},{"id":"c","text":"going"}],"correctOptionId":"a","explanation":"He is third-person singular, so the verb takes -es."},{"id":"english-10-present-simple-q2","prompt":"Which sentence describes a routine?","difficulty":"MEDIUM","options":[{"id":"a","text":"I am reading right now."},{"id":"b","text":"I read a book yesterday."},{"id":"c","text":"I read for twenty minutes every night."}],"correctOptionId":"c","explanation":"“Every night” signals a repeated habit."},{"id":"english-10-present-simple-q3","prompt":"Your sister usually ___ breakfast at seven.","difficulty":"APPLIED","options":[{"id":"a","text":"is have"},{"id":"b","text":"has"},{"id":"c","text":"have"}],"correctOptionId":"b","explanation":"Use has with a third-person singular subject."}]'::jsonb, '["english-10-present-simple"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-present-continuous', 2, 'LESSON', 'Present continuous và hành động đang diễn ra', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Dùng am/is/are + V-ing cho việc đang xảy ra quanh thời điểm nói hoặc một tình huống tạm thời."]'::jsonb, '["They are preparing a presentation now."]'::jsonb, '[{"id":"english-10-present-continuous-q1","prompt":"Present continuous uses which structure?","difficulty":"EASY","options":[{"id":"a","text":"do/does + base verb"},{"id":"b","text":"will + verb-ing"},{"id":"c","text":"am/is/are + verb-ing"}],"correctOptionId":"c","explanation":"The auxiliary be is followed by the -ing form."},{"id":"english-10-present-continuous-q2","prompt":"Look! The children ___ in the yard.","difficulty":"MEDIUM","options":[{"id":"a","text":"played"},{"id":"b","text":"are playing"},{"id":"c","text":"play"}],"correctOptionId":"b","explanation":"“Look!” points to an action happening now."},{"id":"english-10-present-continuous-q3","prompt":"Mai normally cycles, but this week she ___ the bus because her bicycle is being repaired.","difficulty":"APPLIED","options":[{"id":"a","text":"is taking"},{"id":"b","text":"takes always"},{"id":"c","text":"take"}],"correctOptionId":"a","explanation":"A temporary situation can use the present continuous."}]'::jsonb, '["english-10-present-continuous"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-past-simple', 3, 'LESSON', 'Past simple và mốc thời gian đã kết thúc', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Dùng quá khứ đơn cho sự việc đã hoàn tất trong quá khứ. Động từ có quy tắc thường thêm -ed; động từ bất quy tắc cần học dạng riêng."]'::jsonb, '["We visited the museum last Saturday. She went there by train."]'::jsonb, '[{"id":"english-10-past-simple-q1","prompt":"Choose the past form of “go”.","difficulty":"EASY","options":[{"id":"a","text":"gone"},{"id":"b","text":"went"},{"id":"c","text":"goed"}],"correctOptionId":"b","explanation":"“Went” is the simple past form; “gone” is the past participle."},{"id":"english-10-past-simple-q2","prompt":"They ___ the clean-up event yesterday.","difficulty":"MEDIUM","options":[{"id":"a","text":"joined"},{"id":"b","text":"join"},{"id":"c","text":"are join"}],"correctOptionId":"a","explanation":"“Yesterday” calls for the past simple."},{"id":"english-10-past-simple-q3","prompt":"Which question is correct?","difficulty":"APPLIED","options":[{"id":"a","text":"Did you saw the notice?"},{"id":"b","text":"Do you saw the notice?"},{"id":"c","text":"Did you see the notice?"}],"correctOptionId":"c","explanation":"After did, use the base form of the verb."}]'::jsonb, '["english-10-past-simple"]'::jsonb)
