insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-conditionals', 13, 'LESSON', 'Câu điều kiện loại 0 và loại 1', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Loại 0 nói quy luật chung: if + hiện tại đơn, hiện tại đơn. Loại 1 nói khả năng tương lai: if + hiện tại đơn, will + động từ nguyên mẫu."]'::jsonb, '["If you heat ice, it melts. If it rains, we will study indoors."]'::jsonb, '[{"id":"english-10-conditionals-q1","prompt":"A general scientific fact usually uses which pattern?","difficulty":"EASY","options":[{"id":"a","text":"If + past, will + past"},{"id":"b","text":"If + will, present"},{"id":"c","text":"If + present, present"}],"correctOptionId":"c","explanation":"Zero conditional uses present simple in both clauses."},{"id":"english-10-conditionals-q2","prompt":"If we finish early, we ___ the exhibition.","difficulty":"MEDIUM","options":[{"id":"a","text":"visiting"},{"id":"b","text":"will visit"},{"id":"c","text":"visited"}],"correctOptionId":"b","explanation":"First conditional uses will + base verb in the likely result."},{"id":"english-10-conditionals-q3","prompt":"If water reaches 100°C at standard pressure, it ___.","difficulty":"APPLIED","options":[{"id":"a","text":"boils"},{"id":"b","text":"will boiled"},{"id":"c","text":"boil yesterday"}],"correctOptionId":"a","explanation":"This describes a general condition and result."}]'::jsonb, '["english-10-conditionals"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-reported-speech', 14, 'LESSON', 'Tường thuật lời nói đơn giản', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Khi tường thuật lời nói ở quá khứ, đại từ và một số thì có thể lùi theo ngữ cảnh. Không đổi máy móc nếu thông tin vẫn đúng hoặc thời điểm không thay đổi."]'::jsonb, '["“I am tired,” Lan said. → Lan said that she was tired."]'::jsonb, '[{"id":"english-10-reported-speech-q1","prompt":"“I am ready,” he said. A common reported form is?","difficulty":"EASY","options":[{"id":"a","text":"He said that he is readyed."},{"id":"b","text":"He said that he was ready."},{"id":"c","text":"He says I am ready yesterday."}],"correctOptionId":"b","explanation":"With a past reporting verb, am commonly shifts to was and pronouns change."},{"id":"english-10-reported-speech-q2","prompt":"Which reporting verb is in the past?","difficulty":"MEDIUM","options":[{"id":"a","text":"said"},{"id":"b","text":"says"},{"id":"c","text":"will say"}],"correctOptionId":"a","explanation":"Said is the past form of say."},{"id":"english-10-reported-speech-q3","prompt":"A speaker says “We live here” and the reporter is describing a past conversation. What should guide tense choice?","difficulty":"APPLIED","options":[{"id":"a","text":"Always change every verb twice"},{"id":"b","text":"Ignore pronouns"},{"id":"c","text":"The reporting context and whether the fact remains true"}],"correctOptionId":"c","explanation":"Reported speech depends on time reference and current truth."}]'::jsonb, '["english-10-reported-speech"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-environment-vocabulary', 15, 'LESSON', 'Từ vựng về môi trường', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Học từ theo cụm và ngữ cảnh: reduce waste, protect wildlife, renewable energy. Dùng từ đúng sắc thái và kết hợp tự nhiên."]'::jsonb, '["Schools can reduce waste by reusing paper and sorting recyclable materials."]'::jsonb, '[{"id":"english-10-environment-vocabulary-q1","prompt":"Which phrase means “giảm rác thải”?","difficulty":"EASY","options":[{"id":"a","text":"reduce waste"},{"id":"b","text":"make waste"},{"id":"c","text":"waste a reduce"}],"correctOptionId":"a","explanation":"Reduce means make something smaller or less."},{"id":"english-10-environment-vocabulary-q2","prompt":"Solar power is an example of ___ energy.","difficulty":"MEDIUM","options":[{"id":"a","text":"single-use"},{"id":"b","text":"polluted"},{"id":"c","text":"renewable"}],"correctOptionId":"c","explanation":"Solar energy is naturally replenished."},{"id":"english-10-environment-vocabulary-q3","prompt":"A class wants to protect local birds. Which action best matches the goal?","difficulty":"APPLIED","options":[{"id":"a","text":"Feed them plastic scraps."},{"id":"b","text":"Keep nesting areas clean and avoid disturbing them."},{"id":"c","text":"Remove every tree near the school."}],"correctOptionId":"b","explanation":"Protecting habitat and reducing disturbance support wildlife."}]'::jsonb, '["english-10-environment-vocabulary"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-reading-strategies', 16, 'LESSON', 'Đọc hiểu: ý chính và chi tiết', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Đọc lướt để nắm chủ đề; đọc quét để tìm tên, số liệu hoặc từ khóa. Suy luận phải dựa trên thông tin văn bản và tránh thêm giả định."]'::jsonb, '["Nếu đoạn nêu ba lợi ích của vận động nhưng không nói thời lượng, không thể kết luận chính xác bao lâu là tối ưu."]'::jsonb, '[{"id":"english-10-reading-strategies-q1","prompt":"Skimming is mainly used to find?","difficulty":"EASY","options":[{"id":"a","text":"Every punctuation mark"},{"id":"b","text":"A word''s spelling only"},{"id":"c","text":"The general idea"}],"correctOptionId":"c","explanation":"Skimming quickly identifies the overall topic and structure."},{"id":"english-10-reading-strategies-q2","prompt":"Scanning is useful when you need to find?","difficulty":"MEDIUM","options":[{"id":"a","text":"A new paragraph to add"},{"id":"b","text":"A specific date or name"},{"id":"c","text":"The author''s entire life story"}],"correctOptionId":"b","explanation":"Scanning searches selectively for a particular detail."},{"id":"english-10-reading-strategies-q3","prompt":"The text says a park opened in 2022 and attracts many families. Can you infer its exact visitor count?","difficulty":"APPLIED","options":[{"id":"a","text":"No, the exact number is not given."},{"id":"b","text":"Yes, it must be 2,022."},{"id":"c","text":"Yes, every family visits daily."}],"correctOptionId":"a","explanation":"Inference must stay within what the text supports."}]'::jsonb, '["english-10-reading-strategies"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('english', 10, 'intro-2026.1', 'english-10-paragraph-writing', 17, 'LESSON', 'Viết đoạn văn tiếng Anh có mạch lạc', 'Tiếng Anh: ngữ pháp, từ vựng và giao tiếp nền tảng', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Một đoạn ngắn thường có câu chủ đề, các câu hỗ trợ và câu kết hoặc chuyển ý. Dùng từ nối đúng quan hệ, kiểm tra hòa hợp chủ-vị và dấu câu."]'::jsonb, '["Topic sentence: “Walking to school can benefit students.” Supporting details explain exercise and reduced traffic."]'::jsonb, '[{"id":"english-10-paragraph-writing-q1","prompt":"What does a topic sentence usually do?","difficulty":"EASY","options":[{"id":"a","text":"Replace all supporting details"},{"id":"b","text":"State the paragraph''s main idea"},{"id":"c","text":"List every source"}],"correctOptionId":"b","explanation":"The topic sentence guides the paragraph''s focus."},{"id":"english-10-paragraph-writing-q2","prompt":"Choose the correct connector for a contrast.","difficulty":"MEDIUM","options":[{"id":"a","text":"However"},{"id":"b","text":"Because of"},{"id":"c","text":"For example of"}],"correctOptionId":"a","explanation":"However introduces a contrasting idea."},{"id":"english-10-paragraph-writing-q3","prompt":"Which paragraph plan is clearest?","difficulty":"APPLIED","options":[{"id":"a","text":"Unrelated facts → new topic → title"},{"id":"b","text":"Only a list of connectors"},{"id":"c","text":"Main idea → reasons/examples → closing sentence"}],"correctOptionId":"c","explanation":"A logical order helps readers follow the argument."}]'::jsonb, '["english-10-paragraph-writing"]'::jsonb)
