ifficulty":"EASY","options":[{"id":"a","text":"Dự báo thời tiết"},{"id":"b","text":"Di tích và hiện vật vật chất"},{"id":"c","text":"Tin đồn chưa kiểm chứng"}],"correctOptionId":"b","explanation":"Đồ vật và di tích cung cấp bằng chứng vật chất về hoạt động con người."},{"id":"history-10-prehistory-q2","prompt":"Vì sao bối cảnh tìm thấy hiện vật quan trọng?","difficulty":"MEDIUM","options":[{"id":"a","text":"Nó giúp xác định niên đại và mối liên hệ"},{"id":"b","text":"Nó làm hiện vật tự nói mọi điều"},{"id":"c","text":"Nó thay thế việc bảo quản"}],"correctOptionId":"a","explanation":"Vị trí, lớp đất và vật đi kèm ảnh hưởng cách diễn giải."},{"id":"history-10-early-civilizations-q1","prompt":"Sông có thể hỗ trợ cư dân cổ đại bằng cách nào?","difficulty":"EASY","options":[{"id":"a","text":"Nước, đất canh tác và giao thông"},{"id":"b","text":"Tự động tạo nhà nước hiện đại"},{"id":"c","text":"Loại bỏ mọi thiên tai"}],"correctOptionId":"a","explanation":"Sông tạo điều kiện nhưng xã hội vẫn cần tổ chức và thích nghi."},{"id":"history-10-early-civilizations-q2","prompt":"Chữ viết cổ thường giúp gì cho nhà nước?","difficulty":"MEDIUM","options":[{"id":"a","text":"Thay thế mọi hoạt động sản xuất"},{"id":"b","text":"Bảo đảm mọi người biết đọc"},{"id":"c","text":"Ghi chép giao dịch, luật lệ hoặc sự kiện"}],"correctOptionId":"c","explanation":"Ghi chép hỗ trợ quản lý nhưng mức biết chữ khác nhau."},{"id":"history-10-india-china-q1","prompt":"Khi so sánh hai nền văn minh, bước đầu nên làm gì?","difficulty":"EASY","options":[{"id":"a","text":"Gộp mọi thế kỉ"},{"id":"b","text":"Chọn một bên làm chuẩn duy nhất"},{"id":"c","text":"Xác định thời kì và tiêu chí chung"}],"correctOptionId":"c","explanation":"Tiêu chí và mốc thời gian rõ giúp so sánh công bằng."},{"id":"history-10-india-china-q2","prompt":"Một truyền thống tư tưởng kéo dài qua nhiều triều đại có nghĩa là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Mọi cư dân đều nghĩ giống nhau"},{"id":"b","text":"Có sự kế thừa v