values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-review-1', 6, 'FIVE_LESSON_REVIEW', 'Ôn tập 1', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"economics_law-10-scarcity-choice-q1","prompt":"Chi phí cơ hội là gì?","difficulty":"EASY","options":[{"id":"a","text":"Lợi ích tốt nhất bị bỏ qua khi lựa chọn"},{"id":"b","text":"Tổng mọi khoản tiền đã chi"},{"id":"c","text":"Giá rẻ nhất trên thị trường"}],"correctOptionId":"a","explanation":"Nó phản ánh phương án tốt nhất đã không chọn."},{"id":"economics_law-10-scarcity-choice-q2","prompt":"Nguồn lực khan hiếm có nghĩa là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không tồn tại"},{"id":"b","text":"Luôn miễn phí"},{"id":"c","text":"Không đủ để đáp ứng mọi nhu cầu cùng lúc"}],"correctOptionId":"c","explanation":"Khan hiếm làm nảy sinh lựa chọn và phân bổ nguồn lực."},{"id":"economics_law-10-economic-actors-q1","prompt":"Doanh nghiệp thường có vai trò nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ ban hành luật"},{"id":"b","text":"Chỉ tiêu dùng cuối cùng"},{"id":"c","text":"Tổ chức sản xuất hàng hóa hoặc dịch vụ"}],"correctOptionId":"c","explanation":"Doanh nghiệp kết hợp nguồn lực để tạo sản phẩm hoặc dịch vụ."},{"id":"economics_law-10-economic-actors-q2","prompt":"Nhà nước có thể cung cấp dịch vụ công nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Chỉ quảng cáo"},{"id":"b","text":"Giáo dục công lập"},{"id":"c","text":"Mọi hàng hóa tư nhân miễn phí"}],"correctOptionId":"b","explanation":"Dịch vụ công phục vụ lợi ích chung và được tổ chức theo chính sách."},{"id":"economics_law-10-market-q1","prompt":"Thị trường cần có yếu tố nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ Nhà nước"},{"id":"b","text":"Người mua, người bán và trao đổi"},{"id":"c","text":"Chỉ một nhà kho"}],"correctOptionId":"b","explanation":"Thị trường hình thành từ các quan hệ trao đổi hàng hóa, dịch vụ."},{"id":"economics_law-10-market-q2","prompt":"Giá cả có thể truyền tín hiệu gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Thông tin về cung cầu và mức khan hiếm"},{"id":"b","text":"Mọi thông tin cá nhân của người mua"},{"id":"c","text":"Bảo đảm chất lượng tuyệt đối"}],"correctOptionId":"a","explanation":"Giá là tín hiệu hữu ích nhưng không phản ánh đầy đủ mọi thuộc tính."},{"id":"economics_law-10-supply-demand-q1","prompt":"Cầu có bao gồm điều gì ngoài mong muốn mua?","difficulty":"EASY","options":[{"id":"a","text":"Khả năng thanh toán"},{"id":"b","text":"Sở thích không liên quan giá"},{"id":"c","text":"Nguồn cung của doanh nghiệp"}],"correctOptionId":"a","explanation":"Cầu kinh tế gắn với mong muốn và khả năng mua."},{"id":"economics_law-10-supply-demand-q2","prompt":"Cân bằng thị trường khi nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Giá bằng 0"},{"id":"b","text":"Mọi người mua cùng một món"},{"id":"c","text":"Lượng cung bằng lượng cầu"}],"correctOptionId":"c","explanation":"Tại cân bằng, kế hoạch mua và bán tương thích về lượng."},{"id":"economics_law-10-competition-q1","prompt":"Một lợi ích tiềm năng của cạnh tranh là?","difficulty":"EASY","options":[{"id":"a","text":"Bảo đảm mọi doanh nghiệp luôn lời"},{"id":"b","text":"Xóa nhu cầu pháp luật"},{"id":"c","text":"Khuyến khích nâng chất lượng và đổi mới"}],"correctOptionId":"c","explanation":"Cạnh tranh có thể thúc đẩy cải tiến nhưng kết quả không được bảo đảm."},{"id":"economics_law-10-competition-q2","prompt":"Tung tin sai về đối thủ là hành vi nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Bảo vệ người tiêu dùng"},{"id":"b","text":"Cạnh tranh không lành mạnh"},{"id":"c","text":"Cạnh tranh bằng chất lượng"}],"correctOptionId":"b","explanation":"Thông tin gian dối làm méo mó quyết định và gây thiệt hại."}]'::jsonb, '["economics_law-10-scarcity-choice","economics_law-10-economic-actors","economics_law-10-market","economics_law-10-supply-demand","economics_law-10-competition"]'::jsonb)
