insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-money-banking', 7, 'LESSON', 'Tiền, thanh toán và ngân hàng', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Tiền làm phương tiện trao đổi, đơn vị đo giá trị và phương tiện cất giữ giá trị. Ngân hàng nhận tiền gửi, cung cấp dịch vụ thanh toán và cấp tín dụng theo điều kiện."]'::jsonb, '["Chuyển khoản giúp thanh toán không dùng tiền mặt nhưng người dùng cần bảo vệ mã xác thực."]'::jsonb, '[{"id":"economics_law-10-money-banking-q1","prompt":"Một chức năng cơ bản của tiền là?","difficulty":"EASY","options":[{"id":"a","text":"Bảo đảm mọi khoản đầu tư sinh lời"},{"id":"b","text":"Phương tiện trao đổi"},{"id":"c","text":"Thay thế mọi quy định"}],"correctOptionId":"b","explanation":"Tiền giúp trao đổi hàng hóa, dịch vụ thuận tiện hơn."},{"id":"economics_law-10-money-banking-q2","prompt":"Mã OTP nên được xử lí thế nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không chia sẻ cho người khác"},{"id":"b","text":"Gửi cho người tự xưng nhân viên"},{"id":"c","text":"Đăng công khai"}],"correctOptionId":"a","explanation":"Mã xác thực có thể cho phép giao dịch, cần bảo mật."},{"id":"economics_law-10-money-banking-q3","prompt":"Tin nhắn lạ yêu cầu chuyển tiền để “mở khóa tài khoản”. Nên làm gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Bấm liên kết ngay"},{"id":"b","text":"Gửi mật khẩu để xác minh"},{"id":"c","text":"Liên hệ ngân hàng qua kênh chính thức trước khi thao tác"}],"correctOptionId":"c","explanation":"Kênh chính thức giúp kiểm tra yêu cầu và tránh lừa đảo."}]'::jsonb, '["economics_law-10-money-banking"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-credit', 8, 'LESSON', 'Tín dụng và vay có trách nhiệm', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Tín dụng là quan hệ vay và hoàn trả theo thỏa thuận, thường gồm lãi và thời hạn. Trước khi vay cần tính tổng nghĩa vụ, khả năng trả và đọc điều kiện hợp đồng."]'::jsonb, '["Khoản vay nhỏ với phí cao có thể tốn kém hơn dự kiến nếu chỉ nhìn số tiền nhận."]'::jsonb, '[{"id":"economics_law-10-credit-q1","prompt":"Trước khi vay, cần xem điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Lãi, phí, thời hạn và khả năng trả"},{"id":"b","text":"Chỉ khoản tiền nhận"},{"id":"c","text":"Lời hứa miệng duy nhất"}],"correctOptionId":"a","explanation":"Tổng nghĩa vụ thanh toán quyết định tính phù hợp của khoản vay."},{"id":"economics_law-10-credit-q2","prompt":"Lãi suất thấp nhưng có nhiều phí ẩn. Người vay nên?","difficulty":"MEDIUM","options":[{"id":"a","text":"Chỉ so con số quảng cáo"},{"id":"b","text":"Ký ngay"},{"id":"c","text":"Đọc toàn bộ điều khoản và hỏi rõ tổng chi phí"}],"correctOptionId":"c","explanation":"Phí ảnh hưởng tổng chi phí thực."},{"id":"economics_law-10-credit-q3","prompt":"Bạn không chắc có thể trả khoản vay đúng hạn. Lựa chọn an toàn hơn là?","difficulty":"APPLIED","options":[{"id":"a","text":"Bỏ qua hợp đồng"},{"id":"b","text":"Hoãn quyết định và lập lại ngân sách"},{"id":"c","text":"Vay thêm nơi khác ngay"}],"correctOptionId":"b","explanation":"Đánh giá sức trả trước giúp tránh vòng xoáy nợ."}]'::jsonb, '["economics_law-10-credit"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-state-budget', 9, 'LESSON', 'Ngân sách nhà nước', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Ngân sách nhà nước là dự toán thu, chi được cơ quan có thẩm quyền quyết định theo luật. Chi ngân sách hướng tới nhiệm vụ công và phải được quản lí, giám sát."]'::jsonb, '["Thu ngân sách có thể dùng cho trường học, y tế và hạ tầng theo kế hoạch được phê duyệt."]'::jsonb, '[{"id":"economics_law-10-state-budget-q1","prompt":"Ngân sách nhà nước chủ yếu phản ánh gì?","difficulty":"EASY","options":[{"id":"a","text":"Thu nhập của một gia đình"},{"id":"b","text":"Giá cổ phiếu"},{"id":"c","text":"Các khoản thu và chi công theo kế hoạch"}],"correctOptionId":"c","explanation":"Ngân sách công được lập và quyết định theo quy định."},{"id":"economics_law-10-state-budget-q2","prompt":"Vì sao cần giám sát chi tiêu công?","difficulty":"MEDIUM","options":[{"id":"a","text":"Để không cần báo cáo"},{"id":"b","text":"Bảo đảm đúng mục đích và trách nhiệm giải trình"},{"id":"c","text":"Để bỏ mọi dịch vụ công"}],"correctOptionId":"b","explanation":"Giám sát giúp sử dụng nguồn lực công minh bạch."},{"id":"economics_law-10-state-budget-q3","prompt":"Một dự án công tăng chi phí so với dự toán. Cần làm gì?","difficulty":"APPLIED","options":[{"id":"a","text":"Công khai căn cứ, điều chỉnh theo quy định và giám sát"},{"id":"b","text":"Che giấu số liệu"},{"id":"c","text":"Tự ý chuyển quỹ"}],"correctOptionId":"a","explanation":"Điều chỉnh chi cần căn cứ và tuân thủ quy trình pháp luật."}]'::jsonb, '["economics_law-10-state-budget"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-taxes', 10, 'LESSON', 'Thuế và trách nhiệm công dân', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Thuế là khoản nộp bắt buộc theo luật để tạo nguồn lực cho nhiệm vụ công. Loại thuế, người nộp và cách tính phụ thuộc quy định pháp luật; không suy diễn nghĩa vụ từ lời truyền miệng."]'::jsonb, '["Khi mua hàng, hóa đơn giúp ghi nhận giao dịch và quyền lợi bảo hành, đồng thời hỗ trợ kê khai đúng."]'::jsonb, '[{"id":"economics_law-10-taxes-q1","prompt":"Thuế có đặc điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ do người nước ngoài nộp"},{"id":"b","text":"Được quy định và thu theo pháp luật"},{"id":"c","text":"Luôn là khoản tự nguyện"}],"correctOptionId":"b","explanation":"Nghĩa vụ thuế được xác lập trong quy định pháp luật."},{"id":"economics_law-10-taxes-q2","prompt":"Khi chưa rõ nghĩa vụ thuế cá nhân, nên tìm thông tin ở đâu?","difficulty":"MEDIUM","options":[{"id":"a","text":"Cơ quan thuế hoặc văn bản chính thức"},{"id":"b","text":"Tin nhắn không nguồn"},{"id":"c","text":"Bình luận ẩn danh"}],"correctOptionId":"a","explanation":"Nguồn chính thức giúp xác định quy định hiện hành."},{"id":"economics_law-10-taxes-q3","prompt":"Một cửa hàng đề nghị không xuất hóa đơn để giảm giá. Người mua nên cân nhắc?","difficulty":"APPLIED","options":[{"id":"a","text":"Đồng ý mọi điều kiện"},{"id":"b","text":"Cung cấp OTP"},{"id":"c","text":"Yêu cầu chứng từ hợp lệ để bảo vệ quyền lợi và tuân thủ quy định"}],"correctOptionId":"c","explanation":"Chứng từ giúp chứng minh giao dịch; nghĩa vụ cụ thể theo luật áp dụng."}]'::jsonb, '["economics_law-10-taxes"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-production', 11, 'LESSON', 'Sản xuất, chi phí và năng suất', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Sản xuất kết hợp lao động, vốn, tài nguyên và công nghệ để tạo hàng hóa, dịch vụ. Năng suất là kết quả tạo ra trên một đơn vị đầu vào trong khoảng thời gian xác định."]'::jsonb, '["Nếu cùng số giờ làm tạo nhiều sản phẩm đạt chuẩn hơn, năng suất lao động tăng."]'::jsonb, '[{"id":"economics_law-10-production-q1","prompt":"Năng suất lao động thường so sánh gì?","difficulty":"EASY","options":[{"id":"a","text":"Sản lượng với lượng lao động hoặc thời gian"},{"id":"b","text":"Giá bán với màu bao bì"},{"id":"c","text":"Thuế với dân số"}],"correctOptionId":"a","explanation":"Cần xác định đầu ra và đầu vào để tính năng suất."},{"id":"economics_law-10-production-q2","prompt":"Chi phí cố định thường thay đổi thế nào khi sản lượng ngắn hạn đổi?","difficulty":"MEDIUM","options":[{"id":"a","text":"Luôn tăng gấp đôi"},{"id":"b","text":"Bằng 0"},{"id":"c","text":"Không đổi ngay theo từng đơn vị sản phẩm"}],"correctOptionId":"c","explanation":"Chi phí cố định không phụ thuộc trực tiếp sản lượng trong phạm vi nhất định."},{"id":"economics_law-10-production-q3","prompt":"Xưởng muốn tăng lợi nhuận mà vẫn giữ chất lượng. Hướng phù hợp là?","difficulty":"APPLIED","options":[{"id":"a","text":"Ghi sai khối lượng"},{"id":"b","text":"Giảm lãng phí và cải thiện quy trình"},{"id":"c","text":"Bớt nguyên liệu dưới chuẩn"}],"correctOptionId":"b","explanation":"Nâng hiệu quả không nên vi phạm chất lượng hay quyền lợi khách hàng."}]'::jsonb, '["economics_law-10-production"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-review-2', 12, 'FIVE_LESSON_REVIEW', 'Ôn tập 2', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"economics_law-10-money-banking-q1","prompt":"Một chức năng cơ bản của tiền là?","difficulty":"EASY","options":[{"id":"a","text":"Bảo đảm mọi khoản đầu tư sinh lời"},{"id":"b","text":"Phương tiện trao đổi"},{"id":"c","text":"Thay thế mọi quy định"}],"correctOptionId":"b","explanation":"Tiền giúp trao đổi hàng hóa, dịch vụ thuận tiện hơn."},{"id":"economics_law-10-money-banking-q2","prompt":"Mã OTP nên được xử lí thế nào?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không chia sẻ cho người khác"},{"id":"b","text":"Gửi cho người tự xưng nhân viên"},{"id":"c","text":"Đăng công khai"}],"correctOptionId":"a","explanation":"Mã xác thực có thể cho phép giao dịch, cần bảo mật."},{"id":"economics_law-10-credit-q1","prompt":"Trước khi vay, cần xem điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Lãi, phí, thời hạn và khả năng trả"},{"id":"b","text":"Chỉ khoản tiền nhận"},{"id":"c","text":"Lời hứa miệng duy nhất"}],"correctOptionId":"a","explanation":"Tổng nghĩa vụ thanh toán quyết định tính phù hợp của khoản vay."},{"id":"economics_law-10-credit-q2","prompt":"Lãi suất thấp nhưng có nhiều phí ẩn. Người vay nên?","difficulty":"MEDIUM","options":[{"id":"a","text":"Chỉ so con số quảng cáo"},{"id":"b","text":"Ký ngay"},{"id":"c","text":"Đọc toàn bộ điều khoản và hỏi rõ tổng chi phí"}],"correctOptionId":"c","explanation":"Phí ảnh hưởng tổng chi phí thực."},{"id":"economics_law-10-state-budget-q1","prompt":"Ngân sách nhà nước chủ yếu phản ánh gì?","difficulty":"EASY","options":[{"id":"a","text":"Thu nhập của một gia đình"},{"id":"b","text":"Giá cổ phiếu"},{"id":"c","text":"Các khoản thu và chi công theo kế hoạch"}],"correctOptionId":"c","explanation":"Ngân sách công được lập và quyết định theo quy định."},{"id":"economics_law-10-state-budget-q2","prompt":"Vì sao cần giám sát chi tiêu công?","difficulty":"MEDIUM","options":[{"id":"a","text":"Để không cần báo cáo"},{"id":"b","text":"Bảo đảm đúng mục đích và trách nhiệm giải trình"},{"id":"c","text":"Để bỏ mọi dịch vụ công"}],"correctOptionId":"b","explanation":"Giám sát giúp sử dụng nguồn lực công minh bạch."},{"id":"economics_law-10-taxes-q1","prompt":"Thuế có đặc điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ do người nước ngoài nộp"},{"id":"b","text":"Được quy định và thu theo pháp luật"},{"id":"c","text":"Luôn là khoản tự nguyện"}],"correctOptionId":"b","explanation":"Nghĩa vụ thuế được xác lập trong quy định pháp luật."},{"id":"economics_law-10-taxes-q2","prompt":"Khi chưa rõ nghĩa vụ thuế cá nhân, nên tìm thông tin ở đâu?","difficulty":"MEDIUM","options":[{"id":"a","text":"Cơ quan thuế hoặc văn bản chính thức"},{"id":"b","text":"Tin nhắn không nguồn"},{"id":"c","text":"Bình luận ẩn danh"}],"correctOptionId":"a","explanation":"Nguồn chính thức giúp xác định quy định hiện hành."},{"id":"economics_law-10-production-q1","prompt":"Năng suất lao động thường so sánh gì?","difficulty":"EASY","options":[{"id":"a","text":"Sản lượng với lượng lao động hoặc thời gian"},{"id":"b","text":"Giá bán với màu bao bì"},{"id":"c","text":"Thuế với dân số"}],"correctOptionId":"a","explanation":"Cần xác định đầu ra và đầu vào để tính năng suất."},{"id":"economics_law-10-production-q2","prompt":"Chi phí cố định thường thay đổi thế nào khi sản lượng ngắn hạn đổi?","difficulty":"MEDIUM","options":[{"id":"a","text":"Luôn tăng gấp đôi"},{"id":"b","text":"Bằng 0"},{"id":"c","text":"Không đổi ngay theo từng đơn vị sản phẩm"}],"correctOptionId":"c","explanation":"Chi phí cố định không phụ thuộc trực tiếp sản lượng trong phạm vi nhất định."}]'::jsonb, '["economics_law-10-money-banking","economics_law-10-credit","economics_law-10-state-budget","economics_law-10-taxes","economics_law-10-production"]'::jsonb)
