values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-digital-citizenship', 17, 'LESSON', 'Công dân số và an toàn giao dịch', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '["Trong môi trường số, cần bảo vệ dữ liệu cá nhân, kiểm tra nguồn và thận trọng với yêu cầu chuyển tiền. Quyền riêng tư và trách nhiệm pháp luật vẫn áp dụng trên mạng."]'::jsonb, '["Không gửi mật khẩu, mã OTP hoặc ảnh giấy tờ cho tài khoản chưa xác minh."]'::jsonb, '[{"id":"economics_law-10-digital-citizenship-q1","prompt":"Thông tin nào không nên gửi cho người lạ qua chat?","difficulty":"EASY","options":[{"id":"a","text":"Chủ đề học tập"},{"id":"b","text":"Mật khẩu và mã OTP"},{"id":"c","text":"Tên một cuốn sách"}],"correctOptionId":"b","explanation":"Mật khẩu và OTP có thể cho phép truy cập hoặc giao dịch."},{"id":"economics_law-10-digital-citizenship-q2","prompt":"Một đường link yêu cầu đăng nhập lại ngân hàng và tạo cảm giác khẩn cấp. Nên?","difficulty":"MEDIUM","options":[{"id":"a","text":"Mở ứng dụng/kênh chính thức để kiểm tra độc lập"},{"id":"b","text":"Nhập thông tin ngay"},{"id":"c","text":"Gửi mã xác thực cho người gửi"}],"correctOptionId":"a","explanation":"Tạo áp lực khẩn cấp là dấu hiệu cần thận trọng."},{"id":"economics_law-10-digital-citizenship-q3","prompt":"Bạn nhận được ảnh chụp tin đồn về một bạn học. Cách ứng xử phù hợp là?","difficulty":"APPLIED","options":[{"id":"a","text":"Chia sẻ để mọi người tự đoán"},{"id":"b","text":"Thêm số điện thoại vào bài"},{"id":"c","text":"Không phát tán; xác minh và tôn trọng quyền riêng tư"}],"correctOptionId":"c","explanation":"Không lan truyền thông tin chưa kiểm chứng giúp hạn chế gây hại."}]'::jsonb, '["economics_law-10-digital-citizenship"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;
insert into public.mentor_course_units(subject_id,grade,course_version,unit_id,position,kind,title,course_title,source_note,guidance,examples,questions,sources)
values ('economics_law', 10, 'intro-2026.1', 'economics_law-10-review-3', 18, 'FIVE_LESSON_REVIEW', 'Ôn tập 3', 'Giáo dục kinh tế và pháp luật: lựa chọn kinh tế và công dân', '15 bài nhập môn lớp 10 do AI Mentor biên soạn theo yêu cầu cần đạt chung của Chương trình GDPT 2018; không sao chép một bộ SGK và chưa phủ toàn bộ năm học. Bài đầu vào dùng hai câu mỗi bài đã xuất bản để ước lượng nền tảng và đề xuất bài có thể bỏ qua. Nội dung cần giáo viên rà soát trước khi dùng chính thức.', '[]'::jsonb, '[]'::jsonb, '[{"id":"economics_law-10-consumer-rights-q1","prompt":"Thông tin nào người mua nên xem trước khi chọn sản phẩm?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ màu quảng cáo"},{"id":"b","text":"Mật khẩu người bán"},{"id":"c","text":"Thành phần, hướng dẫn, giá và cảnh báo"}],"correctOptionId":"c","explanation":"Thông tin sản phẩm giúp quyết định an toàn và phù hợp."},{"id":"economics_law-10-consumer-rights-q2","prompt":"Sản phẩm có lỗi, bước hữu ích là?","difficulty":"MEDIUM","options":[{"id":"a","text":"Đăng thông tin cá nhân của nhân viên"},{"id":"b","text":"Giữ bằng chứng mua hàng và liên hệ kênh khiếu nại"},{"id":"c","text":"Xóa hóa đơn"}],"correctOptionId":"b","explanation":"Bằng chứng và kênh chính thức hỗ trợ xử lí minh bạch."},{"id":"economics_law-10-law-and-norms-q1","prompt":"Pháp luật khác tập quán ở điểm nào?","difficulty":"EASY","options":[{"id":"a","text":"Không áp dụng chung"},{"id":"b","text":"Có hiệu lực và cơ chế bảo đảm theo Nhà nước"},{"id":"c","text":"Luôn do một gia đình đặt ra"}],"correctOptionId":"b","explanation":"Pháp luật có tính bắt buộc chung và cơ chế thực thi."},{"id":"economics_law-10-law-and-norms-q2","prompt":"Mọi hành vi bị chê trách có tự động là vi phạm pháp luật không?","difficulty":"MEDIUM","options":[{"id":"a","text":"Không"},{"id":"b","text":"Có"},{"id":"c","text":"Chỉ khi lên mạng"}],"correctOptionId":"a","explanation":"Đánh giá đạo đức và xác định vi phạm luật là hai việc khác nhau."},{"id":"economics_law-10-legal-responsibility-q1","prompt":"Trách nhiệm pháp lí nên được xác định dựa trên?","difficulty":"EASY","options":[{"id":"a","text":"Quy định và trình tự có thẩm quyền"},{"id":"b","text":"Tin đồn"},{"id":"c","text":"Lượt bình chọn mạng"}],"correctOptionId":"a","explanation":"Việc xác định cần chứng cứ và quy trình theo luật."},{"id":"economics_law-10-legal-responsibility-q2","prompt":"Khi chứng kiến sự việc chưa rõ, nên làm gì?","difficulty":"MEDIUM","options":[{"id":"a","text":"Đăng tên người bị nghi ngay"},{"id":"b","text":"Tự xử phạt"},{"id":"c","text":"Ghi nhận thông tin cần thiết và báo kênh phù hợp"}],"correctOptionId":"c","explanation":"Cách tiếp cận an toàn tôn trọng quy trình và quyền cá nhân."},{"id":"economics_law-10-rights-duties-q1","prompt":"Thực hiện quyền của mình cần tôn trọng điều gì?","difficulty":"EASY","options":[{"id":"a","text":"Chỉ ý muốn cá nhân"},{"id":"b","text":"Tin chưa kiểm chứng"},{"id":"c","text":"Quyền và lợi ích hợp pháp của người khác"}],"correctOptionId":"c","explanation":"Quyền đi cùng trách nhiệm và giới hạn theo pháp luật."},{"id":"economics_law-10-rights-duties-q2","prompt":"Nguồn nào xác định khung quyền cơ bản của công dân Việt Nam?","difficulty":"MEDIUM","options":[{"id":"a","text":"Bình luận cá nhân"},{"id":"b","text":"Hiến pháp và pháp luật liên quan"},{"id":"c","text":"Một quảng cáo"}],"correctOptionId":"b","explanation":"Hiến pháp là luật cơ bản, các luật cụ thể hóa quyền và nghĩa vụ."},{"id":"economics_law-10-digital-citizenship-q1","prompt":"Thông tin nào không nên gửi cho người lạ qua chat?","difficulty":"EASY","options":[{"id":"a","text":"Chủ đề học tập"},{"id":"b","text":"Mật khẩu và mã OTP"},{"id":"c","text":"Tên một cuốn sách"}],"correctOptionId":"b","explanation":"Mật khẩu và OTP có thể cho phép truy cập hoặc giao dịch."},{"id":"economics_law-10-digital-citizenship-q2","prompt":"Một đường link yêu cầu đăng nhập lại ngân hàng và tạo cảm giác khẩn cấp. Nên?","difficulty":"MEDIUM","options":[{"id":"a","text":"Mở ứng dụng/kênh chính thức để kiểm tra độc lập"},{"id":"b","text":"Nhập thông tin ngay"},{"id":"c","text":"Gửi mã xác thực cho người gửi"}],"correctOptionId":"a","explanation":"Tạo áp lực khẩn cấp là dấu hiệu cần thận trọng."}]'::jsonb, '["economics_law-10-consumer-rights","economics_law-10-law-and-norms","economics_law-10-legal-responsibility","economics_law-10-rights-duties","economics_law-10-digital-citizenship"]'::jsonb)
on conflict(subject_id,grade,unit_id) do nothing;

-- Create the same 10-question reviews used by the app after each five-lesson block.
do $$
declare group_row record; question_set jsonb; quiz_id text;
begin
  for group_row in
    with numbered as (
      select subject_id, grade, unit_id, position, title,
        row_number() over(partition by subject_id, grade order by position, unit_id) as lesson_no
      from public.mentor_course_units
      where kind='LESSON' and grade=10
        and subject_id in ('math','literature','english','history','geography','economics_law')
    )
    select subject_id, grade, ((lesson_no - 1) / 5 + 1)::int as group_no,
      min(lesson_no)::int as first_lesson, max(lesson_no)::int as last_lesson, count(*)::int as lesson_count
    from numbered group by subject_id, grade, ((lesson_no - 1) / 5 + 1)::int having count(*)=5
  loop
    with numbered as (
      select subject_id, grade, unit_id, position, questions,
        row_number() over(partition by subject_id, grade order by position, unit_id) as lesson_no
      from public.mentor_course_units
      where kind='LESSON' and subject_id=group_row.subject_id and grade=group_row.grade
    ), selected as (
      select n.lesson_no, q.ordinality as question_no,
        jsonb_build_object(
          'id',q.value->>'id','prompt',q.value->>'prompt',
          'options',(select coalesce(jsonb_agg(jsonb_build_object('id',upper(o.value->>'id'),'text',o.value->>'text') order by o.ordinality),'[]')
            from jsonb_array_elements(case when jsonb_typeof(q.value->'options')='array' then q.value->'options' else '[]'::jsonb end) with ordinality o(value,ordinality)),
          'correctOption',upper(coalesce(q.value->>'correctOption',q.value->>'correctOptionId')),
          'explanation',coalesce(q.value->>'explanation',''),
          'difficulty',case upper(coalesce(q.value->>'difficulty','MEDIUM')) when 'EASY' then 'EASY' else 'MEDIUM' end,
          'points',10
        ) as item
      from numbered n
      cross join lateral jsonb_array_elements(case when jsonb_typeof(n.questions)='array' then n.questions else '[]'::jsonb end) with ordinality q(value,ordinality)
      where ((n.lesson_no - 1) / 5 + 1)::int=group_row.group_no and q.ordinality<=2
        and jsonb_typeof(n.questions)='array' and q.value ? 'id' and q.value ? 'prompt'
        and coalesce(q.value->>'correctOption',q.value->>'correctOptionId') is not null
        and jsonb_typeof(q.value->'options')='array' and jsonb_array_length(q.value->'options')>=2
      order by n.lesson_no,q.ordinality limit 15
    )
    select coalesce(jsonb_agg(item order by lesson_no,question_no),'[]') into question_set from selected;
    if jsonb_array_length(question_set)=10 then
      quiz_id:='review-'||group_row.subject_id||'-'||group_row.grade||'-'||group_row.group_no;
      insert into public.mentor_library_quizzes(id,title,subject_id,grade,chapter,topic,difficulty,questions,status)
      values (quiz_id,'Ôn tập bài '||group_row.first_lesson||'–'||group_row.last_lesson,group_row.subject_id,group_row.grade,
        'Bài '||group_row.first_lesson||'–'||group_row.last_lesson,'Ôn tập 5 bài gần nhất','MEDIUM',question_set,'PUBLISHED')
      on conflict(id) do nothing;
    end if;
  end loop;
end $$;
commit;
